/* ============================================================
   SHARED DATA STORE — single source of truth for both portals
   ============================================================ */

/* CI API BRIDGE & DATABASE DATA */
var CI_BASE = (function(){
  try {
    var loc = window.location;
    var path = loc.pathname.replace(/\/+$/, '').replace(/\/index\.php.*$/, '');
    return loc.protocol + '//' + loc.host + path + '/index.php/system/';
  } catch(e){
    return '<?php echo site_url("system"); ?>/';
  }
})();
function apiPost(action, data){
  try {
    var form = new FormData();
    for(var k in data){ if(data.hasOwnProperty(k)) form.append(k, data[k]); }
    fetch(CI_BASE + action, { method:'POST', body:form });
  } catch(e){}
}

