/* Consultation Reminder filter helper — completely purges consultation reminders from announcements */
function isConsultReminder(a){
  if(!a) return false;
  var t = (a.title || '').trim().toLowerCase();
  var c = (a.category || '').trim().toLowerCase();
  var txt = (a.text || '').toLowerCase();
  return t === 'consultation reminder' || c === 'consultation reminder' || txt.indexOf('upcoming consultation:') !== -1 || txt.indexOf('please be on time') !== -1;
}

