function savePortalDataLocally(){
  try {
    localStorage.setItem('portal_teacher_data', JSON.stringify(teacherData));
    localStorage.setItem('portal_consultations', JSON.stringify(consultations));
    localStorage.setItem('portal_schedules', JSON.stringify(schedules));
    localStorage.setItem('portal_announcements', JSON.stringify(announcements.filter(function(a){ return !isConsultReminder(a); })));
    localStorage.setItem('portal_ratings', JSON.stringify(ratings));
    localStorage.setItem('portal_shared_msgs', JSON.stringify(sharedMsgs));
    localStorage.setItem('portal_accounts', JSON.stringify(ACCOUNTS));
  } catch(e){}
}

(function mergeLocalOverrides(){
  try {
    var lt = localStorage.getItem('portal_teacher_data');
    if(lt){
      var parsedT = JSON.parse(lt);
      if(Array.isArray(parsedT)){
        parsedT.forEach(function(savedT){
          var cur = teacherData.find(function(x){ return x.name === savedT.name; });
          if(cur){
            if(savedT.subject) cur.subject = savedT.subject;
            if(savedT.status) cur.status = savedT.status;
            if(savedT.bio) cur.bio = savedT.bio;
          }
        });
      }
    }
    var lm = localStorage.getItem('portal_shared_msgs');
    if(lm){
      var parsedM = JSON.parse(lm);
      if(parsedM && typeof parsedM === 'object'){
        Object.keys(parsedM).forEach(function(k){
          if(!sharedMsgs[k]){
            sharedMsgs[k] = parsedM[k];
          } else {
            var existingMap = {};
            sharedMsgs[k].forEach(function(m){
              existingMap[(m.from||'') + '||' + (m.text||'')] = true;
            });
            parsedM[k].forEach(function(m){
              var sig = (m.from||'') + '||' + (m.text||'');
              if(!existingMap[sig]){
                sharedMsgs[k].push(m);
                existingMap[sig] = true;
              }
            });
          }
        });
      }
    }
    var la = localStorage.getItem('portal_announcements');
    if(la){
      var parsedA = JSON.parse(la);
      if(Array.isArray(parsedA)){
        parsedA = parsedA.filter(function(a){ return !isConsultReminder(a); });
        if(parsedA.length > 0){
          announcements = parsedA;
        }
      }
    }
    // Purge any consultation reminder from live announcements
    announcements = announcements.filter(function(a){ return !isConsultReminder(a); });
    localStorage.setItem('portal_announcements', JSON.stringify(announcements));

    var lc = localStorage.getItem('portal_consultations');
    if(lc){
      var parsedC = JSON.parse(lc);
      if(Array.isArray(parsedC)){
        parsedC.forEach(function(sc){
          var cur = consultations.find(function(c){ return c.student === sc.student && c.topic === sc.topic; });
          if(cur){
            cur.status = sc.status;
            if(sc.reply) cur.reply = sc.reply;
          } else if(sc.student && sc.topic) {
            consultations.push(sc);
          }
        });
      }
    }
    var lr = localStorage.getItem('portal_ratings');
    if(lr){
      var parsedR = JSON.parse(lr);
      if(Array.isArray(parsedR)){
        parsedR.forEach(function(sr){
          var cur = ratings.find(function(r){ return r.student === sr.student && r.teacher === sr.teacher; });
          if(cur){
            cur.stars = sr.stars;
            cur.feedback = sr.feedback;
          } else if(sr.student && sr.teacher) {
            ratings.push(sr);
          }
        });
      }
    }
    var ls = localStorage.getItem('portal_schedules');
    if(ls){
      var parsedS = JSON.parse(ls);
      if(Array.isArray(parsedS) && parsedS.length > schedules.length){
        schedules = parsedS;
      }
    }
    // Restore active message selections if saved
    var savedSC = localStorage.getItem('portal_scurrent');
    if(savedSC && teacherData.some(function(t){ return t.name === savedSC; })) sCurrent = savedSC;
    var savedTC = localStorage.getItem('portal_tcurrent');
    if(savedTC && (ACCOUNTS.student.some(function(s){ return s.name === savedTC; }) || consultations.some(function(c){ return c.student === savedTC; }) || Object.keys(sharedMsgs).some(function(k){ return k.indexOf('||' + savedTC) !== -1; }))) tCurrent_student = savedTC;
  } catch(e){}
})();

/* Keep teacher dropdowns and teacher list dynamic whenever subjects are modified */
function updateTeacherDropdowns(){
  try {
    var cf = document.getElementById('cf-teacher');
    var rf = document.getElementById('rf-teacher');
    var sName = (currentAccount && currentAccount.name) ? currentAccount.name : 'Reimark Amaro';

    // 1. Consultation booking dropdown has all faculty
    if(cf && teacherData && teacherData.length){
      var cfVal = cf.value ? cf.value.split(' — ')[0].trim() : '';
      cf.innerHTML = teacherData.map(function(t){
        var label = t.name + ' — ' + (t.subject || 'Faculty');
        return '<option value="' + t.name.replace(/"/g, '&quot;') + '"' + (cfVal === t.name ? ' selected' : '') + '>' + label + '</option>';
      }).join('');
    }

    // 2. Rating & Feedback dropdown ONLY lists teachers who have completed/answered consulting this student
    var lockedNotice = document.getElementById('rf-locked-notice');
    var formBody = document.getElementById('rf-form-body');
    var statusPill = document.getElementById('rf-status-pill');

    var completedList = (consultations || []).filter(function(c){
      return c.student === sName && (c.status === 'answered' || c.status === 'completed' || !!c.reply);
    });

    var eligibleTeachersMap = {};
    completedList.forEach(function(c){
      if(!eligibleTeachersMap[c.teacher]){
        eligibleTeachersMap[c.teacher] = [];
      }
      if(c.topic && eligibleTeachersMap[c.teacher].indexOf(c.topic) === -1){
        eligibleTeachersMap[c.teacher].push(c.topic);
      }
    });

    var eligibleTeacherNames = Object.keys(eligibleTeachersMap);

    if(rf && lockedNotice && formBody){
      if(eligibleTeacherNames.length === 0){
        // No completed consultations: Lock the rating form
        lockedNotice.style.display = 'block';
        formBody.style.display = 'none';
        if(statusPill) statusPill.style.display = 'none';
      } else {
        // Completed consultations exist: Unlock the rating form
        lockedNotice.style.display = 'none';
        formBody.style.display = 'flex';
        if(statusPill){
          statusPill.style.display = 'inline-block';
          statusPill.textContent = '✓ Unlocked (' + eligibleTeacherNames.length + ' Completed Consultation' + (eligibleTeacherNames.length > 1 ? 's' : '') + ')';
        }
        var rfVal = rf.value ? rf.value.split(' — ')[0].trim() : '';
        rf.innerHTML = eligibleTeacherNames.map(function(tName){
          var tObj = (teacherData || []).find(function(x){ return x.name === tName; });
          var subj = tObj ? (tObj.subject || 'Faculty') : 'Faculty';
          var topics = eligibleTeachersMap[tName].length ? (' · Topic: ' + eligibleTeachersMap[tName].join(', ')) : '';
          var label = tName + ' — ' + subj + topics;
          var isSel = (rfVal === tName || (!rfVal && eligibleTeacherNames[0] === tName));
          return '<option value="' + tName.replace(/"/g, '&quot;') + '"' + (isSel ? ' selected' : '') + '>' + label + '</option>';
        }).join('');
      }
    }

    // 3. Update #sec-s-teachers directory table if present
    var st = document.querySelector('#sec-s-teachers .panel table');
    if(st && teacherData && teacherData.length){
      var rows = '<tr><th>Teacher</th><th>Email</th><th>Subject</th><th>Available Days</th><th>Status</th></tr>';
      teacherData.forEach(function(t){
        var em = t.email || (t.name.toLowerCase().replace(/[^a-z]/g,'') + '@icp.edu.ph');
        var isAvail = (t.status === 'available');
        rows += '<tr>'
          + '<td>' + t.name + '</td>'
          + '<td><a href="mailto:' + em + '" style="color:var(--cyan-deep); text-decoration:none;">' + em + '</a></td>'
          + '<td>' + (t.subject || 'Faculty') + '</td>'
          + '<td>' + (t.days || 'Mon / Wed') + '</td>'
          + '<td><span class="pill ' + (isAvail ? 'green' : 'orange') + '">' + (isAvail ? 'Available' : 'Unavailable') + '</span></td>'
          + '</tr>';
      });
      st.innerHTML = rows;
    }
  } catch(e){}
}
updateTeacherDropdowns();

