/* Live Interactive Notification Toast System */
function showPortalToast(title, msg, icon, badge, badgeColor){
  try {
    var c = document.getElementById('portal-toast-container');
    if(!c){
      c = document.createElement('div');
      c.id = 'portal-toast-container';
      c.style.cssText = 'position:fixed; top:20px; right:20px; z-index:999999; display:flex; flex-direction:column; gap:10px; max-width:350px; width:calc(100vw - 40px); pointer-events:none;';
      document.body.appendChild(c);
    }
    var toast = document.createElement('div');
    toast.className = 'portal-toast-card';
    toast.style.cssText = 'background:var(--paper, #fff); border:1px solid var(--line, #e2e8f0); border-left:4px solid var(--cyan-deep, #1B5E91); box-shadow:0 12px 30px rgba(0,0,0,0.18); border-radius:12px; padding:12px 14px; display:flex; align-items:flex-start; gap:10px; pointer-events:auto; transform:translateX(100%); opacity:0; transition:all .3s cubic-bezier(0.34, 1.56, 0.64, 1);';
    toast.innerHTML = '<div style="font-size:22px; line-height:1;">' + (icon || '🔔') + '</div>'
      + '<div style="flex:1; min-width:0;">'
      +   '<div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">'
      +     '<b style="font-size:13px; color:var(--ink, #0B1E42);">' + title + '</b>'
      +     (badge ? '<span class="pill ' + (badgeColor || 'cyan') + '" style="font-size:9.5px; padding:1px 6px;">' + badge + '</span>' : '')
      +   '</div>'
      +   '<div style="font-size:12px; color:var(--muted, #64748b); margin-top:3px; word-break:break-word; line-height:1.35;">' + msg + '</div>'
      + '</div>';
    c.appendChild(toast);
    requestAnimationFrame(function(){
      toast.style.transform = 'translateX(0)';
      toast.style.opacity = '1';
    });
    setTimeout(function(){
      toast.style.transform = 'translateX(100%)';
      toast.style.opacity = '0';
      setTimeout(function(){ if(toast.parentNode) toast.parentNode.removeChild(toast); }, 350);
    }, 4200);
  } catch(e){}
}
window.showPortalToast = showPortalToast;

/* ============================================================
   AUTH
   ============================================================ */
function togglePw(){
  var pw = document.getElementById('loginPw');
  var label = document.getElementById('pwToggleLabel');
  if(pw.type==='password'){ pw.type='text'; label.textContent='Hide'; }
  else { pw.type='password'; label.textContent='Show'; }
}

async function doLogin(){
  var id = document.getElementById('loginId').value.trim();
  var pw = document.getElementById('loginPw').value;
  var errBox = document.getElementById('loginError');
  var wrap = document.querySelector('.auth-wrap');
  
  if(!id || !pw){
    errBox.textContent = 'Please enter both your ID and password.';
    wrap.classList.remove('shake'); void wrap.offsetWidth; wrap.classList.add('shake');
    return;
  }

  // 1. Try real authentication against CodeIgniter / MySQL database
  try {
    var form = new FormData();
    form.append('account_id', id);
    form.append('password', pw);
    var resp = await fetch(CI_BASE + 'login', { method: 'POST', body: form });
    if(resp.ok){
      var res = await resp.json();
      if(res && res.status === 'success'){
        errBox.textContent = '';
        enterApp(res.role, res.user);
        return;
      } else if(res && res.message && !res.message.includes('provided settings')){
        // Explicit invalid password or account from DB
        errBox.textContent = res.message;
        wrap.classList.remove('shake'); void wrap.offsetWidth; wrap.classList.add('shake');
        return;
      }
    }
  } catch(e){
    // Database offline or starting up, proceed to local match
  }

  // 2. Fallback to cached accounts
  var roles = ['student','teacher','admin'], matchedRole=null, found=null;
  for(var i=0;i<roles.length;i++){
    if(ACCOUNTS[roles[i]]){
      var hit = ACCOUNTS[roles[i]].find(function(a){return (a.id===id || a.num===id) && a.pw===pw;});
      if(hit){matchedRole=roles[i]; found=hit; break;}
    }
  }
  if(!found){
    errBox.textContent='No matching account found. Check your details and try again.';
    wrap.classList.remove('shake'); void wrap.offsetWidth; wrap.classList.add('shake');
    return;
  }
  errBox.textContent='';
  enterApp(matchedRole, found);
}

/* ============================================================
   HERO GREETING BANNER (renders for every account entering app)
   ============================================================ */
function renderHero(role, acc){
  if(!role || !acc) return;
  var app = document.getElementById(role + 'App'); if(!app) return;
  var main = app.querySelector('.main'); if(!main) return;
  var o = main.querySelector('.hero'); if(o) o.remove();
  var h = new Date().getHours(), g = h < 12 ? 'Good morning' : (h < 18 ? 'Good afternoon' : 'Good evening');
  var nm = (acc && acc.name) ? acc.name : (role === 'teacher' ? 'Faculty Member' : (role === 'admin' ? 'Administrator' : 'Student'));
  var sub = {
    student: 'Here is what is happening with your consultations.',
    teacher: 'Review pending consultations and reply to students.',
    admin: 'Overview of everything running on the portal.'
  }[role] || 'Welcome to your ICP consultation portal.';

  var d = document.createElement('div');
  d.className = 'hero';
  d.innerHTML = '<div><h2>' + g + ', ' + nm + ' 👋</h2><p>' + new Date().toLocaleDateString(undefined, {weekday:'long', month:'long', day:'numeric', year:'numeric'}) + ' · ' + sub + '</p></div><div class="qa"></div>';
  var qa = d.querySelector('.qa');
  [].slice.call(app.querySelectorAll('.sidebar-link')).slice(1, 4).forEach(function(l){
    var b = document.createElement('button');
    b.textContent = l.textContent;
    b.onclick = function(){ l.click(); };
    qa.appendChild(b);
  });
  var tb = main.querySelector('.topbar');
  main.insertBefore(d, tb ? tb.nextSibling : main.firstChild);
}
window.renderHero = renderHero;
window.hero = renderHero;

