function createPortalAccount(){
  var role = document.getElementById('na-role').value;
  var name = (document.getElementById('na-name').value || '').trim();
  var id = (document.getElementById('na-id').value || '').trim().toLowerCase();
  var pw = (document.getElementById('na-pw').value || '').trim();
  var num = (document.getElementById('na-num').value || '').trim();
  var email = (document.getElementById('na-email').value || '').trim();
  var subject = (document.getElementById('na-subject') ? document.getElementById('na-subject').value : '').trim();
  var msg = document.getElementById('na-msg');

  if(!name || !id || !pw){
    if(msg){
      msg.style.display = 'block';
      msg.style.background = '#fef2f2';
      msg.style.color = '#991b1b';
      msg.textContent = 'Please fill in Full Name, Account ID, and Password.';
    }
    return;
  }

  // Check if ID already exists
  var allAccs = [].concat(ACCOUNTS.student || [], ACCOUNTS.teacher || [], ACCOUNTS.admin || []);
  if(allAccs.some(function(a){ return a.id === id; })){
    if(msg){
      msg.style.display = 'block';
      msg.style.background = '#fef2f2';
      msg.style.color = '#991b1b';
      msg.textContent = 'Account ID “' + id + '” is already in use. Please choose another ID.';
    }
    return;
  }

  var newAcc = {
    id: id,
    pw: pw,
    name: name,
    num: num || (role === 'teacher' ? ('T-2026-0' + ((ACCOUNTS.teacher||[]).length + 1)) : ('2026-000' + ((ACCOUNTS.student||[]).length + 1) + '-ICP')),
    email: email || (id + '@icp.edu.ph')
  };

  if(!ACCOUNTS[role]) ACCOUNTS[role] = [];
  ACCOUNTS[role].push(newAcc);

  if(role === 'teacher'){
    teacherData.push({
      name: name,
      email: newAcc.email,
      subject: subject || 'General Faculty',
      days: 'Mon / Wed',
      time: '1:00 PM – 4:00 PM',
      status: 'available',
      bio: 'Faculty member at ICP. Teaching ' + (subject || 'General Education') + '.'
    });
  }

  savePortalDataLocally();
  apiPost('create_user', {
    role: role,
    account_id: id,
    password: pw,
    name: name,
    num: newAcc.num,
    email: newAcc.email,
    subject: subject
  });

  renderAdminUsers();
  updateAdminCards();
  updateTeacherDropdowns();

  if(msg){
    msg.style.display = 'block';
    msg.style.background = '#e8f5e9';
    msg.style.color = '#1b5e20';
    msg.textContent = '✓ ' + (role === 'teacher' ? 'Faculty' : 'Student') + ' account for ' + name + ' created! Their personalized dashboard and greeting banner are ready upon login.';
  }

  // Clear inputs
  document.getElementById('na-name').value = '';
  document.getElementById('na-id').value = '';
  document.getElementById('na-pw').value = '';
  document.getElementById('na-num').value = '';
  document.getElementById('na-email').value = '';
  if(document.getElementById('na-subject')) document.getElementById('na-subject').value = '';

  showPortalToast('Account Created', 'New ' + role + ' account active: ' + name, '👤', 'Activated', 'green');
}

/* ============================================================
   APP ENTRY
   ============================================================ */
function enterApp(role, account){
  currentRole = role; currentAccount = account;
  try {
    localStorage.setItem('portal_session_role', role);
    localStorage.setItem('portal_session_account', JSON.stringify(account));
  } catch(e){}
  document.getElementById('authStage').style.display='none';
  document.querySelectorAll('.app').forEach(function(a){a.classList.remove('active');});
  document.getElementById(role+'App').classList.add('active');

  // Render the Hero Greeting Banner for this account
  renderHero(role, account);

  if(role==='student'){
    document.getElementById('s-whoami').textContent = account.name;
    var savedSC = null;
    try { savedSC = localStorage.getItem('portal_scurrent'); } catch(e){}
    if(savedSC && teacherData.some(function(t){ return t.name === savedSC; })){
      sCurrent = savedSC;
    } else {
      sCurrent = studentDefaultTeacher[account.name] || 'Ms. Dhay Ann Dalaota';
    }
    updateTeacherDropdowns();
    updateStudentCards();
    go('student','s-home');
    showTeacherView('sched');
    showConsultView('pending');
    buildStudentMessengerList();
    renderSNotifications();
    renderStudentProfile();
  } else if(role==='teacher'){
    document.getElementById('t-whoami').textContent = account.name;
    var savedTC = null;
    try { savedTC = localStorage.getItem('portal_tcurrent'); } catch(e){}
    if(savedTC && ACCOUNTS.student.some(function(s){ return s.name === savedTC; })){
      tCurrent_student = savedTC;
    } else {
      var myStudents = getStudentsForTeacher(account.name);
      tCurrent_student = myStudents.length ? myStudents[0].student : 'Reimark Amaro';
    }
    tCurrent_channel = chanKey(account.name, tCurrent_student);
    updateTeacherCards();
    go('teacher','t-home');
    tHomeView('announce');
    renderTAnnouncements();
    renderTeacherConsultTable();
    renderTeacherSchedule();
    renderTeacherRating();
    buildTeacherMessengerList();
    renderTNotifications();
    renderTeacherProfile();
  } else {
    updateAdminCards();
    renderAdminUsers();
    renderAdminProfile();
    go('admin','a-home');
  }
}

/* ============================================================
   NAVIGATION
   ============================================================ */
function go(role, sec){
  try { localStorage.setItem('portal_current_sec', sec); } catch(e){}
  if(sec==='a-home'){setTimeout(function(){updateAdminCards();renderAdminUsers();renderAdminProfile();},50);}
  if(sec==='a-users'){setTimeout(function(){renderAdminUsers();updateAdminCards();renderAdminProfile();},50);}
  if(sec==='a-profile'){setTimeout(function(){renderAdminProfile();},50);}
  if(sec==='s-home'){setTimeout(function(){showTeacherView('sched');showConsultView('pending');},50);}
  if(sec==='s-consultation'||sec==='s-teachers'||sec==='s-feedback'){setTimeout(function(){updateTeacherDropdowns();},50);}
  if(sec==='s-history'){setTimeout(function(){renderSHistory();},50);}
  if(sec==='s-announcements'){setTimeout(function(){renderSAnnouncements();},50);}
  if(sec==='s-notifications'){setTimeout(function(){renderSNotifications();},50);}
  if(sec==='t-home'){setTimeout(function(){tHomeView('announce');},50);}
  if(sec==='t-dashboard'){setTimeout(function(){renderTeacherDashboardList();renderTeacherSchedule();updateTeacherCards();},50);}
  if(sec==='t-rating'){setTimeout(function(){renderTeacherRating();},50);}
  if(sec==='t-announcements'){setTimeout(function(){renderTAnnouncements();},50);}
  if(sec==='t-notifications'){setTimeout(function(){renderTNotifications();},50);}
  if(sec==='t-schedule'){setTimeout(function(){renderTeacherSchedule();},50);}
  if(sec==='s-profile'){setTimeout(function(){renderStudentProfile();},50);}
  if(sec==='t-profile'){setTimeout(function(){renderTeacherProfile();},50);}
  if(sec==='t-messages'){
    setTimeout(function(){
      var savedTC = null;
      try { savedTC = localStorage.getItem('portal_tcurrent'); } catch(e){}
      if(savedTC) tCurrent_student = savedTC;
      buildTeacherMessengerList();
      openTChat(tCurrent_student);
    },50);
  }
  if(sec==='s-messages'){
    setTimeout(function(){
      var savedSC = null;
      try { savedSC = localStorage.getItem('portal_scurrent'); } catch(e){}
      if(savedSC) sCurrent = savedSC;
      buildStudentMessengerList();
      openSChat(sCurrent);
    },50);
  }
  document.querySelectorAll('#'+role+'App .sidebar-link').forEach(function(l){
    l.classList.toggle('active', l.dataset.sec===sec);
  });
  document.querySelectorAll('#'+role+'App .app-section').forEach(function(s){
    s.classList.toggle('active', s.id==='sec-'+sec);
  });
  var titleMap = {
    's-home':'Dashboard','s-teachers':'Teachers & Schedule','s-consultation':'Consultation',
    's-messages':'Messages','s-history':'Consultation History','s-announcements':'Announcements',
    's-notifications':'Notifications','s-profile':'Profile',
    't-home':'Home','t-dashboard':'Students Dashboard','t-consultation':'Consultation',
    't-messages':'Messages','t-schedule':'Schedule','t-rating':'Rating & Feedback',
    't-announcements':'Announcements','t-notifications':'Notifications','t-profile':'Profile',
    'a-home':'Dashboard','a-users':'Users','a-profile':'Profile'
  };
  var titleEl = document.getElementById(role==='student'?'s-title':(role==='teacher'?'t-title':'a-title'));
  if(titleEl && titleMap[sec]) titleEl.textContent = titleMap[sec];
}

function logout(){
  try { fetch(CI_BASE + 'logout'); } catch(e){}
  try {
    localStorage.removeItem('portal_session_role');
    localStorage.removeItem('portal_session_account');
    localStorage.removeItem('portal_current_sec');
  } catch(e){}
  document.querySelectorAll('.app').forEach(function(a){a.classList.remove('active');});
  document.getElementById('authStage').style.display='flex';
  document.getElementById('loginId').value='';
  document.getElementById('loginPw').value='';
  currentRole=null; currentAccount=null;
}

/* ============================================================
   STUDENT — CARDS
   ============================================================ */
function updateStudentCards(){
  var myConsults = consultations.filter(function(c){return c.student===(currentAccount?currentAccount.name:'Reimark Amaro');});
  document.getElementById('s-count-teachers').textContent = teacherData.filter(function(t){return t.status==='available';}).length;
  document.getElementById('s-count-pending').textContent  = myConsults.filter(function(c){return c.status==='pending';}).length;
  document.getElementById('s-count-answered').textContent = myConsults.filter(function(c){return c.status==='answered';}).length;
}

/* ============================================================
   PROFILE — shared helper + student/teacher render & save
   ============================================================ */
// initials helper is declared globally above

/* ADMIN — live totals, counted from the shared data so they stay current */
function updateAdminCards(){
  var students={}, teachers={};
  ACCOUNTS.student.forEach(function(a){students[a.name]=1;});
  consultations.forEach(function(c){if(c.student) students[c.student]=1;});
  ratings.forEach(function(r){if(r.student) students[r.student]=1;});
  schedules.forEach(function(x){if(x.student) students[x.student]=1;});
  ACCOUNTS.teacher.forEach(function(a){teachers[a.name]=1;});
  teacherData.forEach(function(t){teachers[t.name]=1;});
  var se=document.getElementById('a-total-students'), te=document.getElementById('a-total-teachers');
  if(se) se.textContent=Object.keys(students).length;
  if(te) te.textContent=Object.keys(teachers).length;
}

function renderAdminUsers(){
  var teacherTbody = document.getElementById('a-teachers-tbody');
  var studentTbody = document.getElementById('a-students-tbody');

  // 1. TEACHERS TABLE: Display Name, Subject Topic, and Faculty ID (plus email and status)
  if(teacherTbody){
    var renderedTeachers = {};
    var tRows = '';
    var teacherCount = 0;

    teacherData.forEach(function(t){
      if(renderedTeachers[t.name]) return;
      renderedTeachers[t.name] = true;
      teacherCount++;

      var acc = (ACCOUNTS.teacher || []).find(function(a){ return a.name === t.name; }) || {};
      var facId = acc.num || ('T-2026-0' + teacherCount);
      var email = t.email || acc.email || (t.name.toLowerCase().replace(/[^a-z]/g,'') + '@icp.edu.ph');
      var isAvail = (t.status === 'available');

      tRows += '<tr>'
        + '<td>'
        +   '<div style="display:flex; align-items:center; gap:12px;">'
        +     '<div class="av" style="width:36px; height:36px; font-size:12px; font-weight:700;">' + initials(t.name) + '</div>'
        +     '<div>'
        +       '<div style="font-weight:700; font-size:14px; color:var(--navy-deep);">' + t.name + '</div>'
        +       '<div style="font-size:12px; color:var(--muted);">' + (t.days || 'Mon / Wed') + ' • ' + (t.time || 'Office Hours') + '</div>'
        +     '</div>'
        +   '</div>'
        + '</td>'
        + '<td><span class="pill cyan" style="font-size:12px; font-weight:600;">' + (t.subject || 'Faculty') + '</span></td>'
        + '<td><code style="font-size:13px; font-weight:700; color:var(--navy-deep); background:rgba(44,178,224,0.12); padding:3px 8px; border-radius:6px;">' + facId + '</code></td>'
        + '<td><a href="mailto:' + email + '" style="color:var(--cyan-deep); text-decoration:none; font-size:13px; font-weight:500;">' + email + '</a></td>'
        + '<td><span class="pill ' + (isAvail ? 'green' : 'orange') + '">' + (isAvail ? 'Available' : 'Unavailable') + '</span></td>'
        + '</tr>';
    });

    teacherTbody.innerHTML = tRows;
    var tPill = document.getElementById('a-teachers-count-pill');
    if(tPill) tPill.textContent = teacherCount + ' Faculty Members';
    var te = document.getElementById('a-total-teachers');
    if(te) te.textContent = teacherCount;
  }

  // 2. STUDENTS TABLE: Display Name and Student No. (plus email, consultations, status)
  if(studentTbody){
    var renderedStudents = {};
    var sRows = '';
    var studentCount = 0;

    (ACCOUNTS.student || []).forEach(function(s){
      if(renderedStudents[s.name]) return;
      renderedStudents[s.name] = true;
      studentCount++;

      var cCount = consultations.filter(function(c){ return c.student === s.name; }).length;
      var email = s.email || (s.id + '@icp.edu.ph');
      var sNum = s.num || ('2026-000' + studentCount + '-ICP');

      sRows += '<tr>'
        + '<td>'
        +   '<div style="display:flex; align-items:center; gap:12px;">'
        +     '<div class="av" style="width:36px; height:36px; font-size:12px; font-weight:700; background:linear-gradient(135deg,var(--cyan-deep),var(--navy));">' + initials(s.name) + '</div>'
        +     '<div>'
        +       '<div style="font-weight:700; font-size:14px; color:var(--navy-deep);">' + s.name + '</div>'
        +     '</div>'
        +   '</div>'
        + '</td>'
        + '<td><code style="font-size:13px; font-weight:700; color:var(--navy-deep); background:rgba(44,178,224,0.12); padding:3px 8px; border-radius:6px;">' + sNum + '</code></td>'
        + '<td><a href="mailto:' + email + '" style="color:var(--cyan-deep); text-decoration:none; font-size:13px; font-weight:500;">' + email + '</a></td>'
        + '<td><span class="pill ' + (cCount > 0 ? 'cyan' : 'orange') + '" style="font-size:11.5px;">' + cCount + ' Consultation' + (cCount !== 1 ? 's' : '') + '</span></td>'
        + '<td><span class="pill green">Active</span></td>'
        + '</tr>';
    });

    studentTbody.innerHTML = sRows;
    var sPill = document.getElementById('a-students-count-pill');
    if(sPill) sPill.textContent = studentCount + ' Enrolled Students';
    var se = document.getElementById('a-total-students');
    if(se) se.textContent = studentCount;
  }
}

function renderAdminProfile(){
  // 1. TEACHERS OVERVIEW: Number of Concerns, Average Rating, Upcoming Schedules
  var teacherTbody = document.getElementById('a-profile-teachers-tbody');
  var totalConcerns = 0;
  var totalSchedules = 0;
  var sumRatings = 0;
  var ratedTeachersCount = 0;
  var teacherRows = '';
  var renderedTeachers = {};
  var tCount = 0;

  teacherData.forEach(function(t){
    if(renderedTeachers[t.name]) return;
    renderedTeachers[t.name] = true;
    tCount++;

    var acc = (ACCOUNTS.teacher || []).find(function(a){ return a.name === t.name; }) || {};
    var facId = acc.num || ('T-2026-0' + tCount);

    // Number of Concerns: pending consultations for this teacher
    var tConsults = consultations.filter(function(c){ return c.teacher === t.name; });
    var tConcerns = tConsults.filter(function(c){ return c.status === 'pending'; }).length;
    totalConcerns += tConcerns;

    // Average Rating:
    var tRatings = ratings.filter(function(r){ return r.teacher === t.name; });
    var avg = tRatings.length ? (Math.round((tRatings.reduce(function(s,r){ return s + r.stars; }, 0) / tRatings.length) * 10) / 10) : 0;
    if(avg > 0){
      sumRatings += avg;
      ratedTeachersCount++;
    }

    // Upcoming Schedules:
    var tScheds = schedules.filter(function(s){ return s.teacher === t.name; }).length;
    totalSchedules += tScheds;

    var starsDisplay = avg > 0 ? (avg.toFixed(1) + ' ★ (' + tRatings.length + ' review' + (tRatings.length !== 1 ? 's' : '') + ')') : 'No ratings yet';

    teacherRows += '<tr>'
      + '<td>'
      +   '<div style="display:flex; align-items:center; gap:10px;">'
      +     '<div class="av" style="width:34px; height:34px; font-size:12px; font-weight:700;">' + initials(t.name) + '</div>'
      +     '<div><b style="color:var(--navy-deep); font-size:13.5px;">' + t.name + '</b></div>'
      +   '</div>'
      + '</td>'
      + '<td><span class="pill cyan" style="font-size:12px;">' + (t.subject || 'Faculty') + '</span></td>'
      + '<td><code style="font-size:12.5px; font-weight:700; color:var(--navy-deep); background:rgba(44,178,224,0.12); padding:3px 8px; border-radius:6px;">' + facId + '</code></td>'
      + '<td><span class="pill ' + (tConcerns > 0 ? 'orange' : 'green') + '">' + tConcerns + ' Concern' + (tConcerns !== 1 ? 's' : '') + '</span></td>'
      + '<td><span class="pill ' + (avg >= 4 ? 'green' : (avg > 0 ? 'orange' : '')) + '" style="font-size:12px;">' + starsDisplay + '</span></td>'
      + '<td><span class="pill cyan">' + tScheds + ' Schedule' + (tScheds !== 1 ? 's' : '') + '</span></td>'
      + '</tr>';
  });

  if(teacherTbody) teacherTbody.innerHTML = teacherRows;

  var overallAvg = ratedTeachersCount > 0 ? (sumRatings / ratedTeachersCount).toFixed(1) : '—';
  var cEl = document.getElementById('a-t-concerns');
  if(cEl) cEl.textContent = totalConcerns;
  var rEl = document.getElementById('a-t-rating');
  if(rEl) rEl.textContent = overallAvg !== '—' ? overallAvg + ' ★' : '—';
  var sEl = document.getElementById('a-t-schedules');
  if(sEl) sEl.textContent = totalSchedules;
  var tPill = document.getElementById('a-profile-teachers-pill');
  if(tPill) tPill.textContent = tCount + ' Faculty Members';

  // 2. STUDENTS OVERVIEW: Total Consultations, Answered, Pending
  var studentTbody = document.getElementById('a-profile-students-tbody');
  var totalConsultsAll = 0;
  var totalAnsweredAll = 0;
  var totalPendingAll = 0;
  var studentRows = '';
  var renderedStudents = {};
  var sCount = 0;

  (ACCOUNTS.student || []).forEach(function(s){
    if(renderedStudents[s.name]) return;
    renderedStudents[s.name] = true;
    sCount++;

    var sNum = s.num || ('2026-000' + sCount + '-ICP');
    var sConsults = consultations.filter(function(c){ return c.student === s.name; });
    var sTotal = sConsults.length;
    var sAnswered = sConsults.filter(function(c){ return c.status === 'answered'; }).length;
    var sPending = sConsults.filter(function(c){ return c.status === 'pending'; }).length;

    totalConsultsAll += sTotal;
    totalAnsweredAll += sAnswered;
    totalPendingAll += sPending;

    studentRows += '<tr>'
      + '<td>'
      +   '<div style="display:flex; align-items:center; gap:10px;">'
      +     '<div class="av" style="width:34px; height:34px; font-size:12px; font-weight:700; background:linear-gradient(135deg,var(--cyan-deep),var(--navy));">' + initials(s.name) + '</div>'
      +     '<div><b style="color:var(--navy-deep); font-size:13.5px;">' + s.name + '</b></div>'
      +   '</div>'
      + '</td>'
      + '<td><code style="font-size:12.5px; font-weight:700; color:var(--navy-deep); background:rgba(44,178,224,0.12); padding:3px 8px; border-radius:6px;">' + sNum + '</code></td>'
      + '<td><span class="pill ' + (sTotal > 0 ? 'cyan' : '') + '">' + sTotal + '</span></td>'
      + '<td><span class="pill green">' + sAnswered + '</span></td>'
      + '<td><span class="pill ' + (sPending > 0 ? 'orange' : '') + '">' + sPending + '</span></td>'
      + '</tr>';
  });

  if(studentTbody) studentTbody.innerHTML = studentRows;

  var stEl = document.getElementById('a-s-total');
  if(stEl) stEl.textContent = totalConsultsAll;
  var saEl = document.getElementById('a-s-answered');
  if(saEl) saEl.textContent = totalAnsweredAll;
  var spEl = document.getElementById('a-s-pending');
  if(spEl) spEl.textContent = totalPendingAll;
  var sPill = document.getElementById('a-profile-students-pill');
  if(sPill) sPill.textContent = sCount + ' Enrolled Students';
}
window.renderAdminProfile = renderAdminProfile;

function renderStudentProfile(){
  var acc=currentAccount||ACCOUNTS.student[0];
  document.getElementById('s-profile-avatar').textContent=initials(acc.name);
  document.getElementById('s-profile-display-name').textContent=acc.name;
  document.getElementById('s-profile-num-display').textContent=acc.num||acc.id;
  document.getElementById('s-profile-id').value=acc.num||acc.id;
  document.getElementById('s-profile-name').value=acc.name;
  document.getElementById('s-profile-email').value=acc.email||'';
  var mine=consultations.filter(function(c){return c.student===acc.name;});
  document.getElementById('s-profile-stat-total').textContent=mine.length;
  document.getElementById('s-profile-stat-answered').textContent=mine.filter(function(c){return c.status==='answered';}).length;
  document.getElementById('s-profile-stat-pending').textContent=mine.filter(function(c){return c.status==='pending';}).length;
}

function saveStudentProfile(){
  var acc=currentAccount; if(!acc) return;
  var oldName=acc.name;
  var newName=document.getElementById('s-profile-name').value.trim()||oldName;
  acc.email=document.getElementById('s-profile-email').value.trim();
  if(newName!==oldName){
    // propagate the rename everywhere this student is referenced so every
    // connected record (consultations, ratings, schedules, messages) stays
    // attached to the same person instead of getting orphaned
    consultations.forEach(function(c){if(c.student===oldName) c.student=newName;});
    ratings.forEach(function(r){if(r.student===oldName) r.student=newName;});
    schedules.forEach(function(s){if(s.student===oldName) s.student=newName;});
    Object.keys(sharedMsgs).forEach(function(key){
      if(key.indexOf('||'+oldName)===key.length-('||'+oldName).length){
        var newKey=key.slice(0,key.length-oldName.length)+newName;
        sharedMsgs[newKey]=sharedMsgs[key];
        delete sharedMsgs[key];
      }
    });
    if(studentDefaultTeacher[oldName]!==undefined){
      studentDefaultTeacher[newName]=studentDefaultTeacher[oldName];
      delete studentDefaultTeacher[oldName];
    }
    acc.name=newName;
    document.getElementById('s-whoami').textContent=newName;
    renderSHistory();
  }
  savePortalDataLocally();
  apiPost('save_student_profile', {account_id: acc.id, old_name: oldName, new_name: newName, email: acc.email});
  renderStudentProfile();
  updateStudentCards();
  var msg=document.getElementById('s-profile-msg');
  msg.style.color='#2e8b3d'; msg.textContent='Profile saved.';
  setTimeout(function(){if(msg) msg.textContent='';},2500);
}

function commitTeachingInfo(){
  var acc=currentAccount; if(!acc) return;
  var t=teacherData.find(function(x){return x.name===acc.name;}); if(!t) return;
  var msg=document.getElementById('t-teaching-msg');
  var subj=document.getElementById('t-profile-subj').value.trim();
  var bio=document.getElementById('t-profile-bio').value.trim();
  if(!subj){msg.style.color='#C0392B'; msg.textContent='Subject cannot be empty.'; return;}
  t.subject=subj; t.bio=bio;
  var subInp=document.getElementById('t-subject-topic');
  if(subInp) subInp.value=subj;
  savePortalDataLocally();
  apiPost('save_teacher_profile', {account_id: acc.id, old_name: acc.name, new_name: acc.name, email: acc.email||'', subject: subj, bio: bio});
  document.getElementById('t-profile-subject-pill').textContent=subj;
  updateTeacherDropdowns();
  var p=document.querySelector('#sec-s-teachers .panel');
  if(p&&window.tcards) p.innerHTML='<h3>Teachers &amp; Schedule</h3>'+tcards();
  if(window.showTeacherView) showTeacherView('sched');
  msg.style.color='#2e8b3d'; msg.textContent='Teaching info saved.';
  setTimeout(function(){msg.textContent='';},2500);
}

function saveSubjectTopic(){
  var acc=currentAccount; if(!acc) return;
  var t=teacherData.find(function(x){return x.name===acc.name;}); if(!t) return;
  var inp=document.getElementById('t-subject-topic');
  var msg=document.getElementById('t-subject-msg');
  var subj=inp ? inp.value.trim() : '';
  if(!subj){
    if(msg){ msg.style.display='inline-block'; msg.style.color='#C0392B'; msg.textContent='Subject topic cannot be empty.'; }
    return;
  }
  t.subject=subj;
  var profSubj=document.getElementById('t-profile-subj');
  if(profSubj) profSubj.value=subj;
  var profPill=document.getElementById('t-profile-subject-pill');
  if(profPill) profPill.textContent=subj;

  savePortalDataLocally();
  apiPost('save_teacher_profile', {
    account_id: acc.id,
    old_name: acc.name,
    new_name: acc.name,
    email: acc.email || t.email || '',
    subject: subj,
    bio: t.bio || ''
  });

  updateTeacherDropdowns();
  var p=document.querySelector('#sec-s-teachers .panel');
  if(p&&window.tcards) p.innerHTML='<h3>Teachers &amp; Schedule</h3>'+tcards();
  if(window.showTeacherView) showTeacherView('sched');

  if(msg){
    msg.style.display='inline-block';
    msg.style.color='#2e8b3d';
    msg.textContent='✓ Subject topic saved and updated across directory.';
    setTimeout(function(){ if(msg) msg.style.display='none'; }, 3000);
  }
}

function renderTeacherProfile(){
  var acc=currentAccount||ACCOUNTS.teacher[0];
  var t=teacherData.find(function(x){return x.name===acc.name;})||{};
  document.getElementById('t-profile-avatar').textContent=initials(acc.name);
  document.getElementById('t-profile-display-name').textContent=acc.name;
  document.getElementById('t-profile-subject-pill').textContent=t.subject||'Faculty';
  document.getElementById('t-profile-num-display').textContent=acc.num||acc.id;
  document.getElementById('t-profile-id').value=acc.num||acc.id;
  document.getElementById('t-profile-name').value=acc.name;
  document.getElementById('t-profile-email').value=acc.email||t.email||'';
  document.getElementById('t-profile-subj').value=t.subject||'';
  document.getElementById('t-profile-bio').value=t.bio||'';
  updateTeacherCards();
}

function saveTeacherProfile(){
  var acc=currentAccount; if(!acc) return;
  var oldName=acc.name;
  var newName=document.getElementById('t-profile-name').value.trim()||oldName;
  acc.email=document.getElementById('t-profile-email').value.trim();
  var subj=document.getElementById('t-profile-subj')?document.getElementById('t-profile-subj').value.trim():'';
  var bio=document.getElementById('t-profile-bio')?document.getElementById('t-profile-bio').value.trim():'';
  var td=teacherData.find(function(x){return x.name===oldName;});
  if(td){
    if(subj) td.subject=subj;
    if(bio) td.bio=bio;
  }
  if(newName!==oldName){
    // propagate the rename everywhere this teacher is referenced so every
    // connected record stays attached to the same person
    consultations.forEach(function(c){if(c.teacher===oldName) c.teacher=newName;});
    ratings.forEach(function(r){if(r.teacher===oldName) r.teacher=newName;});
    schedules.forEach(function(s){if(s.teacher===oldName) s.teacher=newName;});
    announcements.forEach(function(a){if(a.author===oldName) a.author=newName;});
    Object.keys(sharedMsgs).forEach(function(key){
      if(key.indexOf(oldName+'||')===0){
        var newKey=newName+key.slice(oldName.length);
        sharedMsgs[newKey]=sharedMsgs[key];
        delete sharedMsgs[key];
      }
    });
    if(td) td.name=newName;
    Object.keys(studentDefaultTeacher).forEach(function(s){
      if(studentDefaultTeacher[s]===oldName) studentDefaultTeacher[s]=newName;
    });
    if(tCurrent_channel.indexOf(oldName+'||')===0) tCurrent_channel=newName+tCurrent_channel.slice(oldName.length);
    acc.name=newName;
    document.getElementById('t-whoami').textContent=newName;
    renderTeacherConsultTable();
    renderTeacherSchedule();
    renderTeacherRating();
    renderTAnnouncements();
    buildTeacherMessengerList();
  }
  savePortalDataLocally();
  apiPost('save_teacher_profile', {account_id: acc.id, old_name: oldName, new_name: newName, email: acc.email, subject: subj, bio: bio});
  updateTeacherDropdowns();
  renderTeacherProfile();
  var msg=document.getElementById('t-profile-msg');
  msg.style.color='#2e8b3d'; msg.textContent='Profile saved.';
  setTimeout(function(){if(msg) msg.textContent='';},2500);
}

/* ============================================================
   STUDENT — TEACHER LIST
   ============================================================ */
function showTeacherView(view){
  document.querySelectorAll('#sec-s-home .panel:nth-of-type(1) .sub-tab').forEach(function(b){
    b.classList.toggle('active', b.getAttribute('onclick')==="showTeacherView('"+view+"')");
  });
  var body = document.getElementById('teacherViewBody'); var html='';
  if(view==='sched'){
    html='<table><tr><th>Teacher</th><th>Subject</th><th>Days</th><th>Time</th><th>Status</th></tr>';
    teacherData.forEach(function(t){
      html+='<tr><td>'+t.name+'</td><td>'+t.subject+'</td><td>'+t.days+'</td><td>'+t.time+'</td><td><span class="pill '+(t.status==='available'?'green':'orange')+'">'+t.status+'</span></td></tr>';
    });
    html+='</table>';
  } else if(view==='profile'){
    teacherData.forEach(function(t){
      html+='<div class="list-item"><span><b>'+t.name+'</b> — '+t.bio+'</span><span class="pill green">'+t.subject+'</span></div>';
    });
  } else if(view==='subject'){
    teacherData.forEach(function(t){
      html+='<div class="list-item"><span>'+t.name+'</span><span class="pill orange">'+t.subject+'</span></div>';
    });
  }
  body.innerHTML=html;
}

/* ============================================================
   STUDENT — CONSULTATIONS
   ============================================================ */
function showConsultView(view){
  document.querySelectorAll('#sec-s-home .panel:nth-of-type(2) .sub-tab').forEach(function(b){
    b.classList.toggle('active', b.getAttribute('onclick')==="showConsultView('"+view+"')");
  });
  var sName = currentAccount?currentAccount.name:'Reimark Amaro';
  var body = document.getElementById('consultViewBody');
  var filtered = consultations.filter(function(c){return c.student===sName && c.status===view;});
  if(!filtered.length){body.innerHTML='<div class="empty">Nothing here yet.</div>';return;}
  var html='';
  filtered.forEach(function(c){
    html+='<div class="list-item"><span><b>'+c.teacher+'</b> — '+c.topic+(c.reply?'<br><span style="color:var(--muted);font-size:12px;">Reply: '+c.reply+'</span>':'')+'</span>'
         +'<span class="pill '+(c.status==='pending'?'orange':'green')+'">'+c.status+'</span></div>';
  });
  body.innerHTML=html;
}

/* student consultation history page */
function renderSHistory(){
  var sName = currentAccount?currentAccount.name:'Reimark Amaro';
  var tbl = document.getElementById('s-history-table');
  if(!tbl) return;
  var html='<tr><th>Date</th><th>Teacher</th><th>Topic</th><th>Status</th></tr>';
  consultations.filter(function(c){return c.student===sName;}).forEach(function(c){
    html+='<tr><td>'+c.date+'</td><td>'+c.teacher+'</td><td>'+c.topic+'</td><td><span class="pill '+(c.status==='pending'?'orange':'green')+'">'+c.status+'</span></td></tr>';
  });
  tbl.innerHTML=html;
}

function sendConsultation(){
  var teacher = document.getElementById('cf-teacher').value.split(' — ')[0];
  var date    = document.getElementById('cf-date').value;
  var time    = document.getElementById('cf-time').value;
  var q       = document.getElementById('cf-question').value.trim();
  var msg     = document.getElementById('cf-msg');
  if(!date||!time||!q){msg.style.color='#c0405a';msg.textContent='Please fill in date, time and your question.';return;}
  var sName = currentAccount?currentAccount.name:'Reimark Amaro';
  var dateStr = new Date(date).toLocaleDateString('en-US',{month:'short',day:'numeric'});
  consultations.unshift({student:sName, teacher:teacher, topic:q, date:dateStr, status:'pending', reply:''});
  msg.style.color='#2e8b3d';
  msg.textContent='Consultation request sent to '+teacher+' for '+dateStr+' at '+time+'.';
  document.getElementById('cf-question').value='';
  updateStudentCards();
  showConsultView('pending');
  renderTeacherConsultTable();
  // also push to schedules
  schedules.push({student:sName, topic:q, day:new Date(date).toLocaleDateString('en-US',{weekday:'short'}), time:time, teacher:teacher});
  savePortalDataLocally();
  renderTeacherSchedule();
  // sync with CodeIgniter MySQL backend
  apiPost('save_consultation', {student:sName, teacher:teacher, topic:q, date:dateStr, time:time});
  // keep the teacher's Number of Concerns / Upcoming Schedules cards live
  updateTeacherCards();
  // notification
  renderSNotifications();
  if(typeof renderTNotifications === 'function') renderTNotifications();
}

/* ============================================================
   STUDENT — RATING & FEEDBACK
   ============================================================ */
var selectedStudentRating = 5;

document.getElementById('cf-stars') && document.getElementById('cf-stars').addEventListener('click', function(e){
  var v = e.target.getAttribute('data-v'); if(!v) return;
  selectedStudentRating = +v;
  updateStudentStarUI(selectedStudentRating);
});

function updateStudentStarUI(stars){
  var el = document.getElementById('cf-stars');
  if(!el) return;
  el.querySelectorAll('span').forEach(function(s){
    s.style.color = (+s.getAttribute('data-v') <= stars) ? '#f59e0b' : '#cbd5e1';
  });
  var labels = {1:'1 Star — Needs Improvement', 2:'2 Stars — Fair', 3:'3 Stars — Good', 4:'4 Stars — Very Good', 5:'5 Stars — Excellent'};
  var lblEl = document.getElementById('cf-review-display');
  if(lblEl) lblEl.textContent = labels[stars] || (stars + ' Stars');
}

function submitStudentFeedback(){
  var teacherSel = document.getElementById('rf-teacher');
  var tName = teacherSel ? teacherSel.value.split(' — ')[0].trim() : '';
  var sName = (currentAccount && currentAccount.name) ? currentAccount.name : 'Reimark Amaro';
  var msgEl = document.getElementById('rf-msg');

  // Verify that the teacher has actually completed / answered consultation with this student
  var isDone = (consultations || []).some(function(c){
    return c.student === sName && c.teacher === tName && (c.status === 'answered' || c.status === 'completed' || !!c.reply);
  });

  if(!tName || !isDone){
    if(msgEl){
      msgEl.style.display = 'block';
      msgEl.style.background = '#fef2f2';
      msgEl.style.color = '#991b1b';
      msgEl.textContent = '⚠️ Rating and feedback is only available after ' + (tName || 'this teacher') + ' has finished and answered your consultation.';
      setTimeout(function(){ msgEl.style.display = 'none'; }, 5000);
    }
    return;
  }

  var comment = document.getElementById('cf-feedback-comment') ? document.getElementById('cf-feedback-comment').value.trim() : '';
  var anonCb = document.getElementById('rf-anonymous');
  var isAnon = !!(anonCb && anonCb.checked);
  var displayName = isAnon ? 'Anonymous Student' : sName;

  // update or add to ratings
  var existing = ratings.find(function(r){ return (r.student === displayName || (!isAnon && r.student === sName)) && r.teacher === tName; });
  if(existing){
    existing.stars = selectedStudentRating;
    existing.feedback = comment;
    existing.isAnonymous = isAnon;
    existing.student = displayName;
  } else {
    ratings.unshift({student: displayName, teacher: tName, stars: selectedStudentRating, feedback: comment, isAnonymous: isAnon});
  }
  savePortalDataLocally();

  // sync to CodeIgniter MySQL backend
  apiPost('save_rating', {student: displayName, teacher: tName, stars: selectedStudentRating, feedback: comment, is_anonymous: isAnon ? 1 : 0});

  if(msgEl){
    msgEl.style.display = 'block';
    msgEl.style.background = '#e8f5e9';
    msgEl.style.color = '#1b5e20';
    msgEl.textContent = '✓ Rating (' + selectedStudentRating + ' Stars) and feedback for ' + tName + ' successfully submitted' + (isAnon ? ' anonymously!' : '!');
    setTimeout(function(){ msgEl.style.display = 'none'; }, 4000);
  }

  if(document.getElementById('cf-feedback-comment')) document.getElementById('cf-feedback-comment').value = '';
  if(anonCb) anonCb.checked = false;

  updateTeacherCards();
  renderTeacherRating();
  renderSNotifications();
  if(typeof renderTNotifications === 'function') renderTNotifications();
  showPortalToast('Feedback Submitted', 'Thank you! Your ' + selectedStudentRating + '★ feedback was submitted for ' + tName, '⭐', 'Review Saved', 'green');
}

/* ============================================================
   STUDENT — ANNOUNCEMENTS
   ============================================================ */
function renderSAnnouncements(filterCat){
  var el = document.getElementById('s-announce-list');
  if(!el) return;
  var list = announcements.filter(function(a){ return !isConsultReminder(a); });
  if(filterCat && filterCat !== 'all'){
    list = list.filter(function(a){ return (a.category||'General').toLowerCase() === filterCat.toLowerCase(); });
  }
  el.innerHTML = list.map(ann).join('') || '<div class="empty">No announcements matching this category.</div>';
}

/* ============================================================
   SHARED NOTIFICATION STATE & PERSISTENCE
   ============================================================ */
var sNotifFilter = 'all';
var tNotifFilter = 'all';

var readNotifs = (function(){
  try {
    var raw = localStorage.getItem('portal_read_notifs');
    return raw ? JSON.parse(raw) : {};
  } catch(e){ return {}; }
})();

var readTNotifs = (function(){
  try {
    var raw = localStorage.getItem('portal_read_tnotifs');
    return raw ? JSON.parse(raw) : {};
  } catch(e){ return {}; }
})();

function saveReadNotifs(){
  try { localStorage.setItem('portal_read_notifs', JSON.stringify(readNotifs)); } catch(e){}
}
function saveReadTNotifs(){
  try { localStorage.setItem('portal_read_tnotifs', JSON.stringify(readTNotifs)); } catch(e){}
}

/* ============================================================
   STUDENT — NOTIFICATIONS
   ============================================================ */
function filterSNotifications(f){
  sNotifFilter = f;
  document.querySelectorAll('#s-notif-filter-tabs .sub-tab').forEach(function(b){
    b.classList.toggle('active', b.getAttribute('onclick') === "filterSNotifications('" + f + "')");
  });
  renderSNotifications();
}

function clearAllNotifications(){
  var sName = me();
  consultations.filter(function(c){ return c.student === sName; }).forEach(function(c){
    if(c.reply) readNotifs['c_reply_' + c.student + '_' + c.topic + '_' + (c.reply || '')] = true;
    readNotifs['c_pending_' + c.student + '_' + c.topic] = true;
  });
  announcements.filter(function(a){ return !isConsultReminder(a); }).forEach(function(a){ readNotifs['a_' + a.id] = true; });
  ratings.filter(function(r){ return r.student === sName || (r.isAnonymous && r.student === 'Anonymous Student'); }).forEach(function(r){
    readNotifs['s_rf_' + r.teacher + '_' + r.stars] = true;
  });
  Object.keys(sharedMsgs).forEach(function(k){
    var p = k.split('||');
    if(p[1] === sName){
      var msgs = sharedMsgs[k] || [];
      for(var i = msgs.length - 1; i >= 0; i--){
        if(msgs[i].from === 'teacher'){
          readNotifs['smsg_' + p[0] + '_' + i + '_' + (msgs[i].text || '').slice(0, 15)] = true;
          break;
        }
      }
    }
  });
  saveReadNotifs();
  renderSNotifications();
}

function markNotifRead(key, targetSec, param){
  if(key){
    readNotifs[key] = true;
    saveReadNotifs();
  }
  renderSNotifications();
  if(param && typeof openSChat === 'function'){
    openSChat(param);
  }
  if(targetSec && typeof go === 'function'){
    go('student', targetSec);
  } else if(targetSec && typeof jump === 'function'){
    jump(targetSec);
  }
}

function renderSNotifications(){
  var el = document.getElementById('s-notif-list');
  if(!el) return;
  var sName = me();
  var items = [];

  // 1. Consultation replies & pending status
  consultations.filter(function(c){ return c.student === sName; }).forEach(function(c){
    if(c.reply){
      var k = 'c_reply_' + c.student + '_' + c.topic + '_' + (c.reply || '');
      var isNew = !readNotifs[k];
      items.push({
        type: 'reply',
        key: k,
        isNew: isNew,
        title: c.teacher + ' answered your consultation on “' + c.topic + '”',
        detail: 'Reply: ' + c.reply,
        time: c.date || 'Recent',
        badge: 'Reply',
        badgeColor: 'green',
        icon: av(c.teacher),
        action: '<button class="small-btn ghost" style="padding:5px 12px; font-size:12px;" onclick="markNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'s-history\')">View History</button>'
      });
    } else {
      var k = 'c_pending_' + c.student + '_' + c.topic;
      var isNew = !readNotifs[k];
      items.push({
        type: 'reply',
        key: k,
        isNew: isNew,
        title: 'Consultation pending review with ' + c.teacher,
        detail: 'Topic: ' + c.topic + ' · Scheduled for ' + c.date,
        time: c.date || 'Pending',
        badge: 'Pending',
        badgeColor: 'orange',
        icon: av(c.teacher),
        action: '<button class="small-btn ghost" style="padding:5px 12px; font-size:12px;" onclick="markNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'s-history\')">View Status</button>'
      });
    }
  });

  // 2. Announcements
  announcements.filter(function(a){ return !isConsultReminder(a); }).forEach(function(a){
    var k = 'a_' + a.id;
    var isNew = !readNotifs[k];
    items.push({
      type: 'announcements',
      key: k,
      isNew: isNew,
      title: a.title ? a.title : ('Notice from ' + a.author),
      detail: a.text,
      time: a.created_at || 'Recent',
      badge: a.category || 'Notice',
      badgeColor: 'orange',
      icon: '<div class="day" style="font-size:18px;">📢</div>',
      action: '<button class="small-btn ghost" style="padding:5px 12px; font-size:12px;" onclick="markNotifRead(\'' + k + '\', \'s-announcements\')">View Notice</button>'
    });
  });

  // 3. Direct Messages from Teachers
  Object.keys(sharedMsgs).forEach(function(key){
    var parts = key.split('||');
    if(parts[1] === sName){
      var tName = parts[0];
      var msgs = sharedMsgs[key] || [];
      var lastTeacherMsg = null;
      var lastTeacherMsgIdx = -1;
      for(var i = msgs.length - 1; i >= 0; i--){
        if(msgs[i].from === 'teacher'){
          lastTeacherMsg = msgs[i];
          lastTeacherMsgIdx = i;
          break;
        }
      }
      if(lastTeacherMsg){
        var k = 'smsg_' + tName + '_' + lastTeacherMsgIdx + '_' + (lastTeacherMsg.text || '').slice(0, 15);
        var isNew = !readNotifs[k];
        items.push({
          type: 'chats',
          key: k,
          isNew: isNew,
          title: tName + ' sent you a message',
          detail: '“' + lastTeacherMsg.text + '”',
          time: 'Direct Message',
          badge: 'Message',
          badgeColor: 'cyan',
          icon: av(tName),
          action: '<button class="small-btn" style="padding:5px 12px; font-size:12px;" onclick="markNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'s-messages\', \'' + tName.replace(/'/g, "\\'") + '\')">Chat</button>'
        });
      }
    }
  });

  // 4. Ratings & Feedback confirmations
  ratings.filter(function(r){ return r.student === sName || (r.isAnonymous && r.student === 'Anonymous Student'); }).forEach(function(r){
    var k = 's_rf_' + r.teacher + '_' + r.stars;
    var isNew = !readNotifs[k];
    items.push({
      type: 'feedback',
      key: k,
      isNew: isNew,
      title: 'Feedback submitted for ' + r.teacher,
      detail: 'You rated ' + r.stars + ' Stars' + (r.feedback ? ': “' + r.feedback + '”' : '') + (r.isAnonymous ? ' (Submitted anonymously)' : ''),
      time: 'Submitted Review',
      badge: r.stars + '★ Feedback',
      badgeColor: r.stars >= 4 ? 'green' : 'orange',
      icon: av(r.teacher),
      action: '<button class="small-btn ghost" style="padding:5px 12px; font-size:12px;" onclick="markNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'s-teachers\')">View Faculty</button>'
    });
  });

  var unreadCount = items.filter(function(x){ return x.isNew; }).length;
  var badgeEl = document.getElementById('s-notif-badge');
  if(badgeEl){
    badgeEl.textContent = unreadCount;
    badgeEl.style.display = unreadCount > 0 ? 'inline-block' : 'none';
  }

  if(sNotifFilter && sNotifFilter !== 'all'){
    items = items.filter(function(x){ return x.type === sNotifFilter; });
  }

  if(!items.length){
    el.innerHTML = '<div class="empty">No notifications yet.</div>';
    return;
  }

  el.innerHTML = items.map(function(item){
    return '<div class="list-item rich notif-card' + (item.isNew ? ' is-new' : '') + '" onclick="if(event.target.tagName !== \'BUTTON\'){ markNotifRead(\'' + item.key.replace(/'/g, "\\'") + '\'); }" style="align-items:center; padding:14px; border-radius:12px; margin-bottom:10px; cursor:pointer;">'
      + item.icon
      + '<div class="gr" style="flex:1;">'
      +   '<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">'
      +     '<span class="notif-title" style="font-weight:700; font-size:13.5px; color:var(--navy-deep);">' + item.title + '</span>'
      +     '<div style="display:flex; gap:6px; align-items:center;">'
      +       '<span class="pill ' + item.badgeColor + '" style="font-size:11px;">' + item.badge + '</span>'
      +       (item.isNew ? '<span class="pill green" style="font-size:10px;">NEW</span>' : '')
      +       '<small style="color:var(--muted); font-size:11px;">' + item.time + '</small>'
      +     '</div>'
      +   '</div>'
      +   '<small style="color:var(--muted); margin-top:2px; display:block;">' + item.detail + '</small>'
      + '</div>'
      + (item.action ? '<div style="margin-left:12px;">' + item.action + '</div>' : '')
      + '</div>';
  }).join('');
}
window.filterSNotifications = filterSNotifications;
window.clearAllNotifications = clearAllNotifications;
window.markNotifRead = markNotifRead;
window.renderSNotifications = renderSNotifications;

/* ============================================================
   STUDENT — MESSAGES & FACULTY DIRECTORY
   ============================================================ */
var sMsgTab = 'chats';
var acceptedRequests = {};
try { acceptedRequests = JSON.parse(localStorage.getItem('portal_accepted_reqs') || '{}'); } catch(e){}
function saveAcceptedRequests(){
  try { localStorage.setItem('portal_accepted_reqs', JSON.stringify(acceptedRequests)); } catch(e){}
}

function switchSMsgTab(tab){
  sMsgTab = tab;
