}

function acceptMsgRequest(role, otherName){
  var meName = currentAccount ? currentAccount.name : (role === 's' ? 'Reimark Amaro' : 'Ms. Dhay Ann Dalaota');
  var k = role === 's' ? (otherName + '||' + meName) : (meName + '||' + otherName);
  acceptedRequests[k] = true;
  saveAcceptedRequests();
  showPortalToast('Request Accepted', 'Conversation unlocked with ' + otherName, '💬', 'Accepted', 'green');
  if(role === 's'){
    switchSMsgTab('chats');
    openSChat(otherName);
  } else {
    switchTMsgTab('chats');
    openTChat(otherName);
  }
}

function declineMsgRequest(role, otherName){
  var meName = currentAccount ? currentAccount.name : (role === 's' ? 'Reimark Amaro' : 'Ms. Dhay Ann Dalaota');
  var k = role === 's' ? (otherName + '||' + meName) : (meName + '||' + otherName);
  acceptedRequests[k] = 'declined';
  saveAcceptedRequests();
  showPortalToast('Request Declined', 'Declined message request from ' + otherName, 'ℹ️', 'Declined', 'orange');
  if(role === 's') buildStudentMessengerList();
  else buildTeacherMessengerList();
}

function buildStudentMessengerList(filterText){
  var cont = document.getElementById('s-messenger-contacts');
  if(!cont) return;
  var sName = currentAccount ? currentAccount.name : 'Reimark Amaro';
  var teachers = teacherData.slice();

  // Count incoming teacher requests
  var reqCount = 0;
  teachers.forEach(function(t){
    var k = chanKey(t.name, sName);
    var msgs = sharedMsgs[k] || [];
    var isReq = msgs.length && msgs[msgs.length - 1].from === 'teacher' && !acceptedRequests[k];
    if(isReq) reqCount++;
  });
  var reqBadge = document.getElementById('s-reqs-badge');
  if(reqBadge){
    reqBadge.textContent = reqCount;
    reqBadge.style.display = reqCount > 0 ? 'inline-block' : 'none';
  }

  if(filterText){
    var q = filterText.toLowerCase();
    teachers = teachers.filter(function(t){
      return t.name.toLowerCase().indexOf(q) > -1 || (t.subject||'').toLowerCase().indexOf(q) > -1;
    });
  }

  if(sMsgTab === 'requests'){
    var reqTeachers = teachers.filter(function(t){
      var k = chanKey(t.name, sName);
      var msgs = sharedMsgs[k] || [];
      return (msgs.length && msgs[msgs.length - 1].from === 'teacher' && acceptedRequests[k] !== true) || (acceptedRequests[k] === 'pending');
    });
    if(!reqTeachers.length){
      cont.innerHTML = '<div class="empty" style="text-align:center; padding:32px 14px;">'
        + '<div style="font-size:32px; margin-bottom:8px;">📬</div>'
        + '<b style="font-size:13.5px; color:var(--ink);">No Message Requests</b><br>'
        + '<span style="font-size:12px; color:var(--muted);">Inquiries and first-time messages from faculty will appear here.</span>'
        + '</div>';
      return;
    }
    cont.innerHTML = reqTeachers.map(function(t){
      var k = chanKey(t.name, sName);
      var msgs = sharedMsgs[k] || [];
      var last = msgs.length ? msgs[msgs.length - 1].text : 'Teacher sent you an inquiry.';
      return '<div class="messenger-contact" style="padding:12px 14px; border-bottom:1px solid var(--line); display:flex; flex-direction:column; gap:8px;">'
        + '<div style="display:flex; align-items:center; gap:12px;">'
        +   '<div class="messenger-avatar">' + initials(t.name) + '</div>'
        +   '<div style="flex:1; min-width:0;">'
        +     '<div style="font-weight:700; font-size:13px; color:var(--ink);">' + t.name + '</div>'
        +     '<div style="font-size:11.5px; color:var(--muted);">' + (t.subject || 'Faculty') + '</div>'
        +   '</div>'
        + '</div>'
        + '<div style="font-size:12px; background:rgba(0,0,0,0.03); padding:6px 10px; border-radius:6px; color:var(--ink); font-style:italic;">“' + last + '”</div>'
        + '<div style="display:flex; gap:8px; justify-content:flex-end;">'
        +   '<button class="small-btn ghost" style="padding:4px 10px; font-size:11px;" onclick="declineMsgRequest(\'s\', \'' + t.name.replace(/'/g, "\\'") + '\')">Decline</button>'
        +   '<button class="small-btn" style="padding:4px 12px; font-size:11px;" onclick="acceptMsgRequest(\'s\', \'' + t.name.replace(/'/g, "\\'") + '\')">Accept &amp; Chat</button>'
        + '</div>'
        + '</div>';
    }).join('');
    return;
  }

  // Regular 'chats' view
  if(!teachers.length){
    cont.innerHTML = '<div class="empty" style="text-align:center; padding:20px 8px;">No matching faculty found.</div>';
    return;
  }
  cont.innerHTML = teachers.map(function(t){
    var k = chanKey(t.name, sName);
    var msgs = sharedMsgs[k] || [];
    var last = msgs.length ? msgs[msgs.length - 1].text : (t.subject || 'Click to message');
    var isActive = (t.name === sCurrent);
    var isAvail = (t.status === 'available');
    var hasUnread = msgs.length && msgs[msgs.length - 1].from === 'teacher' && !readNotifs['smsg_' + t.name + '_' + (msgs.length - 1) + '_' + (msgs[msgs.length - 1].text || '').slice(0, 15)];
    return '<div class="messenger-contact ' + (isActive ? 'active' : '') + '" data-contact="' + t.name.replace(/"/g, '&quot;') + '" onclick="openSChat(\'' + t.name.replace(/'/g, "\\'") + '\')" style="display:flex; align-items:center; gap:12px; padding:12px 14px; cursor:pointer; border-bottom:1px solid var(--line); transition:background .15s;">'
      + '<div class="messenger-avatar" style="position:relative;">' + initials(t.name)
      + '<span style="position:absolute; bottom:0; right:0; width:10px; height:10px; border-radius:50%; background:' + (isAvail ? '#22c55e' : '#f97316') + '; border:2px solid #fff;"></span>'
      + '</div>'
      + '<div class="messenger-contact-info" style="flex:1; min-width:0;">'
      +   '<div style="display:flex; justify-content:space-between; align-items:center;">'
      +     '<span class="messenger-contact-name" style="font-weight:600; font-size:13px; color:var(--ink); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' + t.name + '</span>'
      +     (hasUnread ? '<span style="width:8px; height:8px; border-radius:50%; background:#ef4444; display:inline-block;"></span>' : '')
      +   '</div>'
      +   '<div class="messenger-contact-preview" style="font-size:11.5px; color:var(--muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:2px;">' + last + '</div>'
      + '</div>'
      + '</div>';
  }).join('');
}

function filterSMessenger(query){
  buildStudentMessengerList(query);
}

function openSChat(teacherName){
  if(!teacherName) return;
  sCurrent = teacherName;
  try { localStorage.setItem('portal_scurrent', teacherName); } catch(e){}
  var sName = (currentAccount && currentAccount.name) ? currentAccount.name : 'Reimark Amaro';
  var t = (teacherData && teacherData.find) ? teacherData.find(function(x){ return x.name === teacherName; }) : null;
  if(!t) t = {name:teacherName, subject:'Faculty', status:'available'};
  var isAvail = (t.status === 'available');

  // 1. Immediately update chat header
  var hdr = document.getElementById('s-chat-header-title');
  if(hdr){
    hdr.innerHTML = '<div style="display:flex; align-items:center; gap:10px;">'
      + '<div class="messenger-avatar" style="width:36px; height:36px; font-size:13px; position:relative;">' + initials(teacherName)
      +   '<span style="position:absolute; bottom:0; right:0; width:9px; height:9px; border-radius:50%; background:' + (isAvail ? '#22c55e' : '#f97316') + '; border:2px solid #fff;"></span>'
      + '</div>'
      + '<div style="min-width:0;">'
      +   '<div style="font-size:14.5px; font-weight:700; color:var(--ink); line-height:1.2; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' + teacherName + '</div>'
      +   '<div style="font-size:11.5px; color:var(--muted); margin-top:2px;">' + (t.subject || 'Faculty') + ' · <span style="color:' + (isAvail ? '#16a34a' : '#ea580c') + '; font-weight:600;">' + (isAvail ? 'Available' : 'Unavailable') + '</span></div>'
      + '</div>'
      + '</div>';
  }

  // 2. Immediately highlight active contact in sidebar list
  document.querySelectorAll('#s-messenger-contacts .messenger-contact').forEach(function(el){
    el.classList.toggle('active', el.getAttribute('data-contact') === teacherName);
  });
  var wrap = document.querySelector('#sec-s-messages .messenger-wrap');
  if(wrap) wrap.classList.add('chat-active');

  // 3. Immediately switch and render chat conversation history
  renderSChat();

  // 4. Focus message input
  var input = document.getElementById('s-chat-input');
  if(input) input.focus();

  // 5. Mark messages as read, unlock in acceptedRequests, and safely update notifications
  try {
    var kChat = chanKey(teacherName, sName);
    acceptedRequests[kChat] = true;
    saveAcceptedRequests();
    var msgsChat = sharedMsgs[kChat] || [];
    for(var i = msgsChat.length - 1; i >= 0; i--){
      if(msgsChat[i].from === 'teacher'){
        readNotifs['smsg_' + teacherName + '_' + i + '_' + (msgsChat[i].text || '').slice(0, 15)] = true;
        break;
      }
    }
    saveReadNotifs();
    if(typeof renderSNotifications === 'function') renderSNotifications();
  } catch(e){
    console.warn('safe notif read error:', e);
  }
}

function renderSChat(){
  var body = document.getElementById('s-chat-thread'); if(!body) return;
  body.innerHTML = '';
  var sName = (currentAccount && currentAccount.name) ? currentAccount.name : 'Reimark Amaro';
  var key = chanKey(sCurrent, sName);
  var msgs = sharedMsgs[key] || [];
  if(!msgs.length){
    body.innerHTML = '<div class="empty" style="text-align:center; padding:45px 16px; margin:auto;">'
      + '<div style="font-size:42px; margin-bottom:12px;">👋</div>'
      + '<b style="font-size:15px; color:var(--ink);">Start chatting with ' + sCurrent + '</b><br>'
      + '<span style="font-size:13px; color:var(--muted); display:block; margin-top:4px;">Send a question, inquiry, or consultation follow-up below!</span>'
      + '</div>';
    return;
  }
  msgs.forEach(function(m){
    var isMe = (m.from === 'student');
    var wrap = document.createElement('div');
    wrap.style.cssText = 'display:flex; flex-direction:column; align-items:' + (isMe ? 'flex-end' : 'flex-start') + '; margin-bottom:10px; width:100%;';
    var lbl = document.createElement('div');
    lbl.style.cssText = 'font-size:10.5px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; color:var(--muted); margin-bottom:3px; padding:0 4px;';
    lbl.textContent = isMe ? 'YOU' : (m.sender || sCurrent);
    var bub = document.createElement('div');
    bub.className = 'msg-bubble ' + (isMe ? 'sent' : 'received');
    bub.style.cssText = isMe
      ? 'background:linear-gradient(135deg, #1B5E91, #2CB2E0); color:#fff; padding:10px 14px; border-radius:18px 18px 4px 18px; max-width:80%; word-break:break-word; font-size:13.5px; line-height:1.45; box-shadow:0 2px 8px rgba(0,0,0,.08);'
      : 'background:var(--paper, #f1f5f9); color:var(--ink, #0B1E42); border:1px solid var(--line, #e2e8f0); padding:10px 14px; border-radius:18px 18px 18px 4px; max-width:80%; word-break:break-word; font-size:13.5px; line-height:1.45; box-shadow:0 2px 8px rgba(0,0,0,.04);';
    bub.textContent = m.text;
    wrap.appendChild(lbl); wrap.appendChild(bub); body.appendChild(wrap);
  });
  body.scrollTop = body.scrollHeight;
}

function sendSChat(){
  var input = document.getElementById('s-chat-input');
  var text = input.value.trim(); if(!text) return;
  var sName = currentAccount ? currentAccount.name : 'Reimark Amaro';
  var key = chanKey(sCurrent, sName);
  if(!sharedMsgs[key]) sharedMsgs[key] = [];
  sharedMsgs[key].push({from:'student', text:text, sender:sName});
  savePortalDataLocally();
  apiPost('send_message', {teacher: sCurrent, student: sName, from_role: 'student', sender: sName, text: text});
  input.value = '';
  renderSChat();
  buildStudentMessengerList();
  if(document.getElementById('t-chat-thread') && tCurrent_channel === key) {
    renderTChat();
    if(typeof buildTeacherMessengerList === 'function') buildTeacherMessengerList();
  }
  updateTeacherCards();
  renderSNotifications();
  if(typeof renderTNotifications === 'function') renderTNotifications();
  showPortalToast('Message Sent', 'Sent to ' + sCurrent + ': “' + text.slice(0, 35) + '”', '💬', 'Sent', 'green');
}

/* ============================================================
   TEACHER — CARDS
   ============================================================ */
function getStudentsForTeacher(tName){
  return consultations.filter(function(c){return c.teacher===tName;});
}

function updateTeacherCards(){
  var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
  var myC=getStudentsForTeacher(tName);
  var concernCount=myC.filter(function(c){return c.status==='pending';}).length;
  var myR=ratings.filter(function(r){return r.teacher===tName;});
  var avg=myR.length?Math.round(myR.reduce(function(s,r){return s+r.stars;},0)/myR.length*10)/10:0;
  var scheduleCount=schedules.filter(function(s){return s.teacher===tName;}).length;
  // Home page cards AND the Students Dashboard page cards both reflect
  // the same live numbers, so a concern/rating/schedule change from the
  // student side updates every card the teacher can see.
  [['t-card-concerns','t-card-concerns2','t-card-concerns3',concernCount],
   ['t-card-rating','t-card-rating2','t-card-rating3', (avg > 0 ? avg + ' ★' : '—')],
   ['t-card-schedules','t-card-schedules2','t-card-schedules3',scheduleCount]
  ].forEach(function(triple){
    for(var i=0;i<triple.length-1;i++){
      var el=document.getElementById(triple[i]); if(el) el.textContent=triple[triple.length-1];
    }
  });
}

/* ============================================================
   TEACHER — CONSULTATION TABLE
   ============================================================ */
function renderTeacherConsultTable(){
  var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
  var tbl=document.getElementById('t-consult-table'); if(!tbl) return;
  var html='<tr><th>Student</th><th>Topic</th><th>Preferred Date</th><th>Action</th></tr>';
  consultations.filter(function(c){return c.teacher===tName&&c.status==='pending';}).forEach(function(c){
    html+='<tr><td>'+c.student+'</td><td>'+c.topic+'</td><td>'+c.date+'</td>'
         +'<td><button class="small-btn" onclick="answerConsult(this,\''+c.student+'\',\''+c.topic+'\')">Answer</button></td></tr>';
  });
  if(!consultations.filter(function(c){return c.teacher===tName&&c.status==='pending';}).length)
    html+='<tr><td colspan="4" style="text-align:center;color:var(--muted);">No pending consultations.</td></tr>';
  tbl.innerHTML=html;
}

function answerConsult(btn, student, topic){
  var c=consultations.find(function(x){return x.student===student&&x.topic===topic&&x.status==='pending';});
  function finish(replyText){
    apiPost('answer_consultation', {student: student, topic: topic, reply: replyText});
    renderTeacherConsultTable();
    renderTeacherDashboardList();
    updateTeacherCards();
    updateStudentCards();
    showConsultView('answered');
    updateTeacherDropdowns();
    renderSNotifications();
    if(typeof renderTNotifications === 'function') renderTNotifications();
    showPortalToast('Consultation Answered', 'Answered consultation for ' + student + ' on “' + topic + '”. Feedback unlocked!', '📋', 'Completed', 'green');
  }
  if(c){
    ccPrompt('Enter your reply for '+student+' ('+topic+'):', function(reply){
      if(reply===null) return;
      var finalReply = reply || 'Your consultation has been answered.';
      c.status='answered'; c.reply=finalReply;
      savePortalDataLocally();
      finish(finalReply);
    });
    return;
  }
  finish('');
}

function renderTeacherDashboardList(){
  var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
  var el=document.getElementById('t-student-list'); if(!el) return;
  var html='<tr><th>Student</th><th>Topic</th><th>Status</th></tr>';
  getStudentsForTeacher(tName).forEach(function(c){
    html+='<tr><td>'+c.student+'</td><td>'+c.topic+'</td><td><span class="pill '+(c.status==='pending'?'orange':'green')+'">'+c.status+'</span></td></tr>';
  });
  el.innerHTML=html;
}

/* ============================================================
   TEACHER — SCHEDULE
   ============================================================ */
function renderTeacherSchedule(){
  var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
  var tObj=teacherData.find(function(x){return x.name===tName;});
  var subInp=document.getElementById('t-subject-topic');
  if(subInp && tObj && tObj.subject){
    subInp.value = tObj.subject;
  }
  var cb = document.getElementById('t-status-toggle');
  var lbl = document.getElementById('t-status-label');
  if(cb && lbl && tObj){
    cb.checked = (tObj.status === 'available');
    lbl.textContent = (tObj.status === 'available' ? 'Available' : 'Unavailable');
    lbl.className = 'pill ' + (tObj.status === 'available' ? 'green' : 'orange');
  }
  var myS=schedules.filter(function(s){return s.teacher===tName;});
  var listHtml = myS.map(function(s){
    return '<div class="list-item"><span>'+s.day+' '+s.time+' — '+s.student+' ('+s.topic+')</span>'
           +'<span class="pill green" style="font-size:11px;">Confirmed</span></div>';
  }).join('') || '<div class="empty">No upcoming schedules.</div>';

  var el=document.getElementById('t-schedule-list');
  if(el) el.innerHTML = listHtml;
  var el2=document.getElementById('t-schedule-list2');
  if(el2) el2.innerHTML = listHtml;
}

/* ============================================================
   TEACHER — RATING
   ============================================================ */
function renderTeacherRating(){
  var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
  var el=document.getElementById('t-rating-list'); if(!el) return;
  var myR=ratings.filter(function(r){return r.teacher===tName;});
  if(!myR.length){el.innerHTML='<div class="empty">No ratings yet.</div>';return;}
  el.innerHTML=myR.map(function(r){
    var stars='★'.repeat(r.stars)+'☆'.repeat(5-r.stars);
    var isAnon = r.isAnonymous || r.student === 'Anonymous Student';
    var dispName = isAnon ? 'Anonymous Student' : r.student;
    var fb = r.feedback ? '<div class="feedback-quote" style="margin-top:8px; padding:10px 14px; background:rgba(44,178,224,0.08); border-left:3px solid var(--cyan-deep); border-radius:6px; font-size:13.5px; color:var(--ink); font-style:italic; line-height:1.45;">“'+r.feedback+'”</div>' : '';
    return '<div class="list-item rich rating-card" style="flex-direction:column; align-items:flex-start; gap:6px; padding:14px; border-radius:12px; border:1px solid var(--line); margin-bottom:10px;">'
      + '<div style="display:flex; justify-content:space-between; width:100%; align-items:center; gap:8px; flex-wrap:wrap;">'
      +   '<span><b>'+dispName+'</b> — <span style="color:#F2A33A; font-size:15px; letter-spacing:1px;">'+stars+'</span></span>'
      +   '<div>'
      +     '<span class="pill '+(r.stars>=4?'green':'orange')+'">'+r.stars+' Star'+(r.stars>1?'s':'')+'</span>'
      +     (isAnon ? '<span class="pill orange" style="font-size:10px; margin-left:6px;">Anonymous</span>' : '')
      +   '</div>'
      + '</div>'
      + fb
      + '</div>';
  }).join('');
}

/* ============================================================
   TEACHER — ANNOUNCEMENTS
   ============================================================ */
var tAnnTab = 'all';
function filterTAnnTab(tab){
  tAnnTab = tab;
  document.querySelectorAll('#t-ann-filter-tabs .sub-tab').forEach(function(b){
    b.classList.toggle('active', b.getAttribute('onclick') === "filterTAnnTab('" + tab + "')");
  });
  renderTAnnouncements();
}

function postAnnouncement(){
  var input = document.getElementById('t-announce-input');
  var text = input.value.trim(); if(!text) return;
  var titleEl = document.getElementById('t-announce-title');
  var title = titleEl ? titleEl.value.trim() : 'Announcement';
  var catEl = document.getElementById('t-announce-category');
  var category = catEl ? catEl.value : 'General';
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  var now = new Date();
  var timeStr = now.toLocaleDateString(undefined, {month:'short', day:'numeric', year:'numeric'}) + ' • ' + now.toLocaleTimeString(undefined, {hour:'numeric', minute:'2-digit'});
  var newAnn = {
    id: Date.now(),
    title: title || 'Announcement',
    category: category,
    text: text,
    author: tName,
    created_at: timeStr
  };
  announcements.unshift(newAnn);
  savePortalDataLocally();
  apiPost('save_announcement', {title: newAnn.title, category: newAnn.category, text: text, author: tName});
  input.value = '';
  if(titleEl) titleEl.value = '';

  var succMsg = document.getElementById('t-announce-success-msg');
  if(!succMsg){
    succMsg = document.createElement('div');
    succMsg.id = 't-announce-success-msg';
    succMsg.style.cssText = 'padding:10px 14px; background:#e8f5e9; color:#1b5e20; font-size:13px; font-weight:600; border-radius:8px; margin-top:10px; display:none;';
    var parentPanel = input.closest('.panel');
    if(parentPanel) parentPanel.appendChild(succMsg);
  }
  if(succMsg){
    succMsg.style.display = 'block';
    succMsg.textContent = '✓ Announcement published successfully! Visible in your published list, the Home screen, and student announcements.';
    setTimeout(function(){ if(succMsg) succMsg.style.display = 'none'; }, 4000);
  }

  renderTAnnouncements();
  tHomeView('announce');
  renderSAnnouncements();
  renderSNotifications();
  if(typeof renderTNotifications === 'function') renderTNotifications();

  showPortalToast('Announcement Published', newAnn.title + ': “' + text.slice(0, 35) + '”', '📢', 'Broadcast', 'cyan');

  var pubPanel = document.getElementById('t-published-announcements-panel');
  if(pubPanel && typeof pubPanel.scrollIntoView === 'function'){
    pubPanel.scrollIntoView({behavior:'smooth'});
  }
}

function deleteAnnouncement(id){
  if(!confirm('Are you sure you want to delete this announcement?')) return;
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  announcements = announcements.filter(function(a){ return a.id != id; });
  savePortalDataLocally();
  apiPost('delete_announcement', {id: id, author: tName});
  renderTAnnouncements();
  tHomeView('announce');
  renderSAnnouncements();
  renderSNotifications();
  if(typeof renderTNotifications === 'function') renderTNotifications();
  showPortalToast('Announcement Deleted', 'Announcement removed from portal feed.', '🗑️', 'Deleted', 'orange');
}

function renderTAnnouncements(){
  var el = document.getElementById('t-announce-list'); if(!el) return;
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  var list = announcements.filter(function(a){ return !isConsultReminder(a); });
  if(tAnnTab === 'my'){
    list = list.filter(function(a){ return a.author === tName || (currentAccount && currentAccount.role === 'admin'); });
  }
  if(!list.length){
    el.innerHTML = '<div class="empty" style="text-align:center; padding:30px 14px;">'
      + '<div style="font-size:32px; margin-bottom:8px;">📢</div>'
      + '<b style="font-size:14px; color:var(--ink);">' + (tAnnTab === 'my' ? 'No Announcements Published by You Yet' : 'No Active Announcements') + '</b><br>'
      + '<span style="font-size:12.5px; color:var(--muted);">' + (tAnnTab === 'my' ? 'Use the form above to publish your first announcement to students.' : 'Announcements posted by faculty and administration will be listed here.') + '</span>'
      + '</div>';
    return;
  }
  el.innerHTML = list.map(function(a){
    var cat = a.category || 'General';
    var time = a.created_at || 'Recently';
    var isMine = a.author === tName || (currentAccount && currentAccount.role === 'admin');
    var catColor = {Academic:'cyan', Consultation:'orange', Urgent:'red', Reminder:'green'}[cat] || 'orange';
    return '<div class="list-item rich ann-card" style="align-items:flex-start; padding:14px; border-radius:12px; background:#fff; border:1px solid var(--line); margin-bottom:10px;">'
      + '<div class="day" style="font-size:18px;">📢</div>'
      + '<div class="gr" style="flex:1;">'
      +   '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px; gap:8px; flex-wrap:wrap;">'
      +     '<span style="font-weight:700; font-size:14.5px; color:var(--navy-deep);">' + (a.title || 'Announcement') + '</span>'
      +     '<div style="display:flex; gap:6px; align-items:center;">'
      +       '<span class="pill ' + catColor + '" style="font-size:11px;">' + cat + '</span>'
      +       '<small style="color:var(--muted); font-size:11px;">' + time + '</small>'
      +     '</div>'
      +   '</div>'
      +   '<p style="margin:4px 0 8px; font-size:13.5px; line-height:1.45; color:var(--ink);">' + a.text + '</p>'
      +   '<div style="display:flex; justify-content:space-between; align-items:center;">'
      +     '<small style="color:var(--muted);">Posted by <b>' + a.author + '</b>' + (isMine ? ' <span class="pill cyan" style="font-size:10px; margin-left:6px;">Your Post</span>' : '') + '</small>'
      +     (isMine && a.id ? '<button class="small-btn ghost" style="padding:4px 10px; font-size:11px; color:#e74c3c; border-color:#fadbd8;" onclick="deleteAnnouncement('+a.id+')">Delete</button>' : '')
      +   '</div>'
      + '</div>'
      + '</div>';
  }).join('');
}

