function tHomeView(view){
  document.querySelectorAll('#sec-t-home .sub-tab').forEach(function(b){
    b.classList.toggle('active',b.getAttribute('onclick')==="tHomeView('"+view+"')");
  });
  var body=document.getElementById('tHomeBody');
  if(!body) return;
  if(view==='announce'){
    var list = announcements.filter(function(a){ return !isConsultReminder(a); });
    body.innerHTML=list.map(function(a){
      var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
      var isMine = a.author === tName;
      return '<div class="list-item rich ann-card" style="align-items:flex-start; padding:12px 14px; border-radius:10px; border:1px solid var(--line); margin-bottom:8px;">'
        + '<div class="day" style="font-size:18px;">📢</div>'
        + '<div class="gr" style="flex:1;">'
        +   '<div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">'
        +     '<b style="font-size:14px; color:var(--navy-deep);">' + (a.title || 'Announcement') + '</b>'
        +     '<span class="pill orange" style="font-size:10.5px;">' + (a.category || 'General') + '</span>'
        +   '</div>'
        +   '<p style="margin:4px 0 6px; font-size:13px; line-height:1.4; color:var(--ink);">' + a.text + '</p>'
        +   '<small style="color:var(--muted);">Posted by <b>' + a.author + '</b>' + (isMine ? ' <span class="pill cyan" style="font-size:10px; margin-left:4px;">(You)</span>' : '') + ' · ' + (a.created_at || 'Recently') + '</small>'
        + '</div>'
        + '</div>';
    }).join('')||'<div class="empty">No announcements.</div>';
  } else {
    var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
    var myR=ratings.filter(function(r){return r.teacher===tName;});
    body.innerHTML=myR.map(function(r){
      var isAnon = r.isAnonymous || r.student === 'Anonymous Student';
      var dispName = isAnon ? 'Anonymous Student' : r.student;
      var icon = isAnon ? '<div class="av" style="background:#94a3b8;">?</div>' : av(r.student);
      return '<div class="list-item rich rating-card" style="align-items:flex-start; padding:12px 14px; border-radius:10px; border:1px solid var(--line); margin-bottom:8px;">'
        + icon
        + '<div class="gr" style="flex:1;">'
        +   '<div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">'
        +     '<b>' + dispName + '</b>'
        +     '<span style="color:#F2A33A; font-size:14px;">' + '★'.repeat(r.stars) + '☆'.repeat(5-r.stars) + '</span>'
        +   '</div>'
        +   (r.feedback ? '<p style="margin:4px 0 0; font-size:13px; color:var(--ink); font-style:italic;">“' + r.feedback + '”</p>' : '')
        + '</div>'
        + '</div>';
    }).join('')||'<div class="empty">No feedback yet.</div>';
  }
}

