   ============================================================ */
function toggleStatus(){
  var cb=document.getElementById('t-status-toggle');
  var lbl=document.getElementById('t-status-label');
  var tName=currentAccount?currentAccount.name:'Ms. Dhay Ann Dalaota';
  var t=teacherData.find(function(x){return x.name===tName;});
  if(cb.checked){
    lbl.textContent='Available'; lbl.className='pill green';
    if(t) t.status='available';
  } else {
    lbl.textContent='Unavailable'; lbl.className='pill orange';
    if(t) t.status='unavailable';
  }
  savePortalDataLocally();
  if(t) apiPost('toggle_status', {name:tName, status:t.status});
  showTeacherView('sched');
  updateStudentCards();
}

/* ============================================================
   TEACHER — MESSAGES & STUDENT INBOX
   ============================================================ */
var tMsgTab = 'chats';
function switchTMsgTab(tab){
  tMsgTab = tab;
  var bChats = document.getElementById('t-tab-btn-chats');
  var bReqs = document.getElementById('t-tab-btn-requests');
  if(bChats) bChats.classList.toggle('active', tab === 'chats');
  if(bReqs) bReqs.classList.toggle('active', tab === 'requests');
  buildTeacherMessengerList();
}

function buildTeacherMessengerList(filterText){
  var cont = document.getElementById('t-messenger-contacts');
  if(!cont) return;
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';

  // Gather all unique students
  var studentsMap = {};
  ACCOUNTS.student.forEach(function(a){
    if(!studentsMap[a.name]){
      studentsMap[a.name] = {name: a.name, num: a.num || a.id, email: a.email || ''};
    }
  });
  consultations.forEach(function(c){
    if(!studentsMap[c.student]){
      studentsMap[c.student] = {name: c.student, num: 'STUDENT', email: ''};
    }
  });
  Object.keys(sharedMsgs).forEach(function(key){
    var parts = key.split('||');
    if(parts[0] === tName && parts[1]){
      if(!studentsMap[parts[1]]){
        studentsMap[parts[1]] = {name: parts[1], num: 'STUDENT', email: ''};
      }
    }
  });

  var students = Object.values(studentsMap);

  // Count incoming student requests
  var reqCount = 0;
  students.forEach(function(s){
    var k = chanKey(tName, s.name);
    var msgs = sharedMsgs[k] || [];
    var isReq = msgs.length && msgs[msgs.length - 1].from === 'student' && !acceptedRequests[k];
    if(isReq) reqCount++;
  });
  var reqBadge = document.getElementById('t-reqs-badge');
  if(reqBadge){
    reqBadge.textContent = reqCount;
    reqBadge.style.display = reqCount > 0 ? 'inline-block' : 'none';
  }

  if(filterText){
    var q = filterText.toLowerCase();
    students = students.filter(function(s){
      return s.name.toLowerCase().indexOf(q) > -1 || (s.num||'').toLowerCase().indexOf(q) > -1;
    });
  }

  if(tMsgTab === 'requests'){
    var reqStudents = students.filter(function(s){
      var k = chanKey(tName, s.name);
      var msgs = sharedMsgs[k] || [];
      return (msgs.length && msgs[msgs.length - 1].from === 'student' && acceptedRequests[k] !== true) || (acceptedRequests[k] === 'pending');
    });
    if(!reqStudents.length){
      cont.innerHTML = '<div class="empty" style="text-align:center; padding:32px 14px;">'
        + '<div style="font-size:32px; margin-bottom:8px;">📬</div>'
        + '<b style="font-size:13.5px; color:var(--ink);">No Message Requests</b><br>'
        + '<span style="font-size:12px; color:var(--muted);">Incoming inquiries from students will appear here.</span>'
        + '</div>';
      return;
    }
    cont.innerHTML = reqStudents.map(function(s){
      var k = chanKey(tName, s.name);
      var msgs = sharedMsgs[k] || [];
      var last = msgs.length ? msgs[msgs.length - 1].text : 'Student sent you a consultation inquiry.';
      return '<div class="messenger-contact" style="padding:12px 14px; border-bottom:1px solid var(--line); display:flex; flex-direction:column; gap:8px;">'
        + '<div style="display:flex; align-items:center; gap:12px;">'
        +   '<div class="messenger-avatar">' + initials(s.name) + '</div>'
        +   '<div style="flex:1; min-width:0;">'
        +     '<div style="font-weight:700; font-size:13px; color:var(--ink);">' + s.name + '</div>'
        +     '<div style="font-size:11.5px; color:var(--muted);">' + (s.num || 'Enrolled Student') + '</div>'
        +   '</div>'
        + '</div>'
        + '<div style="font-size:12px; background:rgba(0,0,0,0.03); padding:6px 10px; border-radius:6px; color:var(--ink); font-style:italic;">“' + last + '”</div>'
        + '<div style="display:flex; gap:8px; justify-content:flex-end;">'
        +   '<button class="small-btn ghost" style="padding:4px 10px; font-size:11px;" onclick="declineMsgRequest(\'t\', \'' + s.name.replace(/'/g, "\\'") + '\')">Decline</button>'
        +   '<button class="small-btn" style="padding:4px 12px; font-size:11px;" onclick="acceptMsgRequest(\'t\', \'' + s.name.replace(/'/g, "\\'") + '\')">Accept &amp; Reply</button>'
        + '</div>'
        + '</div>';
    }).join('');
    return;
  }

  // Regular 'chats' view
  if(!students.length){
    cont.innerHTML = '<div class="empty" style="text-align:center; padding:20px 8px;">No matching students found in inbox.</div>';
    return;
  }

  cont.innerHTML = students.map(function(s){
    var k = chanKey(tName, s.name);
    var msgs = sharedMsgs[k] || [];
    var last = msgs.length ? msgs[msgs.length - 1].text : 'Click to start conversation';
    var hasUnread = msgs.length && msgs[msgs.length - 1].from === 'student' && !readTNotifs['tmsg_' + s.name + '_' + (msgs.length - 1) + '_' + (msgs[msgs.length - 1].text || '').slice(0, 15)];
    var isActive = (s.name === tCurrent_student);
    return '<div class="messenger-contact ' + (isActive ? 'active' : '') + '" data-contact="' + s.name.replace(/"/g, '&quot;') + '" onclick="openTChat(\'' + s.name.replace(/'/g, "\\'") + '\')" style="display:flex; align-items:center; gap:12px; padding:12px 14px; cursor:pointer; border-bottom:1px solid var(--line); transition:background .15s;">'
      + '<div class="messenger-avatar" style="position:relative;">' + initials(s.name)
      + '</div>'
      + '<div class="messenger-contact-info" style="flex:1; min-width:0;">'
      +   '<div style="display:flex; justify-content:space-between; align-items:center;">'
      +     '<span class="messenger-contact-name" style="font-weight:600; font-size:13px; color:var(--ink);">' + s.name + '</span>'
      +     (hasUnread ? '<span style="width:8px; height:8px; border-radius:50%; background:#ef4444; display:inline-block;"></span>' : '<small style="font-size:10.5px; color:var(--muted);">' + (s.num || '') + '</small>')
      +   '</div>'
      +   '<div class="messenger-contact-preview" style="font-size:11.5px; color:var(--muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:2px;">' + last + '</div>'
      + '</div>'
      + '</div>';
  }).join('');
}

function filterTMessenger(query){
  buildTeacherMessengerList(query);
}

function openTChat(studentName){
  if(!studentName) return;
  tCurrent_student = studentName;
  try { localStorage.setItem('portal_tcurrent', studentName); } catch(e){}
  var tName = (currentAccount && currentAccount.name) ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  tCurrent_channel = chanKey(tName, studentName);
  var stuObj = (ACCOUNTS.student && ACCOUNTS.student.find) ? ACCOUNTS.student.find(function(a){ return a.name === studentName; }) : null;
  if(!stuObj) stuObj = {num:'STUDENT'};
  var c = consultations.find(function(x){ return x.student === studentName && x.teacher === tName; }) || {topic:''};

  // 1. Immediately update chat header
  var hdr = document.getElementById('t-chat-header-title');
  if(hdr){
    hdr.innerHTML = '<div style="display:flex; align-items:center; gap:10px;">'
      + '<div class="messenger-avatar" style="width:36px; height:36px; font-size:13px;">' + initials(studentName) + '</div>'
      + '<div style="min-width:0;">'
      +   '<div style="font-size:14.5px; font-weight:700; color:var(--ink); line-height:1.2; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' + studentName + '</div>'
      +   '<div style="font-size:11.5px; color:var(--muted); margin-top:2px;">ID: ' + (stuObj.num || 'Enrolled Student') + (c.topic ? ' · <span class="pill orange" style="font-size:9.5px; padding:1px 6px;">' + c.topic + '</span>' : '') + '</div>'
      + '</div>'
      + '</div>';
  }

  // 2. Immediately highlight active contact
  document.querySelectorAll('#t-messenger-contacts .messenger-contact').forEach(function(el){
    el.classList.toggle('active', el.getAttribute('data-contact') === studentName);
  });
  var wrap = document.querySelector('#sec-t-messages .messenger-wrap');
  if(wrap) wrap.classList.add('chat-active');

  // 3. Immediately switch and render chat conversation history
  renderTChat();

  // 4. Focus message input
  var input = document.getElementById('t-chat-input');
  if(input) input.focus();

  // 5. Mark messages as read, unlock in acceptedRequests, and safely update notifications
  try {
    acceptedRequests[tCurrent_channel] = true;
    saveAcceptedRequests();
    var msgsChatT = sharedMsgs[tCurrent_channel] || [];
    for(var i = msgsChatT.length - 1; i >= 0; i--){
      if(msgsChatT[i].from === 'student'){
        readTNotifs['tmsg_' + studentName + '_' + i + '_' + (msgsChatT[i].text || '').slice(0, 15)] = true;
        break;
      }
    }
    saveReadTNotifs();
    if(typeof renderTNotifications === 'function') renderTNotifications();
  } catch(e){
    console.warn('safe t-notif read error:', e);
  }
}

function renderTChat(){
  var body = document.getElementById('t-chat-thread'); if(!body) return;
  body.innerHTML = '';
  var msgs = sharedMsgs[tCurrent_channel] || [];
  if(!msgs.length){
    body.innerHTML = '<div class="empty" style="text-align:center; padding:45px 16px; margin:auto;">'
      + '<div style="font-size:42px; margin-bottom:12px;">💬</div>'
      + '<b style="font-size:15px; color:var(--ink);">Start direct conversation with ' + tCurrent_student + '</b><br>'
      + '<span style="font-size:13px; color:var(--muted); display:block; margin-top:4px;">Send a message below to start your direct consultation discussion!</span>'
      + '</div>';
    return;
  }
  msgs.forEach(function(m){
    var isMe = (m.from === 'teacher');
    var wrap = document.createElement('div');
    wrap.style.cssText = 'display:flex; flex-direction:column; align-items:' + (isMe ? 'flex-end' : 'flex-start') + '; margin-bottom:10px; width:100%;';
    var lbl = document.createElement('div');
    lbl.style.cssText = 'font-size:10.5px; font-weight:700; letter-spacing:.04em; text-transform:uppercase; color:var(--muted); margin-bottom:3px; padding:0 4px;';
    lbl.textContent = isMe ? 'YOU' : (m.sender || tCurrent_student);
    var bub = document.createElement('div');
    bub.className = 'msg-bubble ' + (isMe ? 'sent' : 'received');
    bub.style.cssText = isMe
      ? 'background:linear-gradient(135deg, #1B5E91, #2CB2E0); color:#fff; padding:10px 14px; border-radius:18px 18px 4px 18px; max-width:80%; word-break:break-word; font-size:13.5px; line-height:1.45; box-shadow:0 2px 8px rgba(0,0,0,.08);'
      : 'background:var(--paper, #f1f5f9); color:var(--ink, #0B1E42); border:1px solid var(--line, #e2e8f0); padding:10px 14px; border-radius:18px 18px 18px 4px; max-width:80%; word-break:break-word; font-size:13.5px; line-height:1.45; box-shadow:0 2px 8px rgba(0,0,0,.04);';
    bub.textContent = m.text;
    wrap.appendChild(lbl); wrap.appendChild(bub); body.appendChild(wrap);
  });
  body.scrollTop = body.scrollHeight;
}

function sendTChat(){
  var input = document.getElementById('t-chat-input');
  var text = input.value.trim(); if(!text) return;
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  if(!sharedMsgs[tCurrent_channel]) sharedMsgs[tCurrent_channel] = [];
  sharedMsgs[tCurrent_channel].push({from:'teacher', text:text, sender:tName});
  savePortalDataLocally();
  apiPost('send_message', {teacher: tName, student: tCurrent_student, from_role: 'teacher', sender: tName, text: text});
  input.value = '';
  renderTChat();
  buildTeacherMessengerList();
  var sName = (currentRole === 'student' && currentAccount) ? currentAccount.name : 'Reimark Amaro';
  if(chanKey(sCurrent, sName) === tCurrent_channel && document.getElementById('s-chat-thread')) {
    renderSChat();
    if(typeof buildStudentMessengerList === 'function') buildStudentMessengerList();
  }
  updateTeacherCards();
  renderTNotifications();
  if(typeof renderSNotifications === 'function') renderSNotifications();
  showPortalToast('Message Sent', 'Sent to ' + tCurrent_student + ': “' + text.slice(0, 35) + '”', '💬', 'Sent', 'green');
}

/* ============================================================
   TEACHER — NOTIFICATIONS
   ============================================================ */
function filterTNotifications(f){
  tNotifFilter = f;
  document.querySelectorAll('#t-notif-filter-tabs .sub-tab').forEach(function(b){
    b.classList.toggle('active', b.getAttribute('onclick') === "filterTNotifications('" + f + "')");
  });
  renderTNotifications();
}

function clearAllTNotifications(){
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  consultations.filter(function(c){ return c.teacher === tName; }).forEach(function(c){
    readTNotifs['c_' + c.student + '_' + c.topic + '_' + c.status] = true;
  });
  ratings.filter(function(r){ return r.teacher === tName; }).forEach(function(r){
    readTNotifs['r_' + r.student + '_' + r.stars + '_' + (r.feedback ? r.feedback.slice(0, 15) : '')] = true;
  });
  Object.keys(sharedMsgs).forEach(function(key){
    var parts = key.split('||');
    if(parts[0] === tName){
      var msgs = sharedMsgs[key] || [];
      for(var i = msgs.length - 1; i >= 0; i--){
        if(msgs[i].from === 'student'){
          readTNotifs['tmsg_' + parts[1] + '_' + i + '_' + (msgs[i].text || '').slice(0, 15)] = true;
          break;
        }
      }
    }
  });
  announcements.filter(function(a){ return !isConsultReminder(a); }).forEach(function(a){ readTNotifs['ta_' + a.id] = true; });
  saveReadTNotifs();
  renderTNotifications();
}

function markTNotifRead(key, targetSec, param){
  if(key){
    readTNotifs[key] = true;
    saveReadTNotifs();
  }
  renderTNotifications();
  if(param && typeof openTChat === 'function'){
    openTChat(param);
  }
  if(targetSec && typeof go === 'function'){
    go('teacher', targetSec);
  }
}

function renderTNotifications(){
  var el = document.getElementById('t-notif-list');
  if(!el) return;
  var tName = currentAccount ? currentAccount.name : 'Ms. Dhay Ann Dalaota';
  var items = [];

  // 1. Consultation requests
  consultations.filter(function(c){ return c.teacher === tName; }).forEach(function(c){
    var k = 'c_' + c.student + '_' + c.topic + '_' + c.status;
    var isNew = (c.status === 'pending') && !readTNotifs[k];
    items.push({
      type: 'consultation',
      key: k,
      isNew: isNew,
      title: 'Consultation request from ' + c.student,
      detail: 'Topic: ' + c.topic + ' · Scheduled: ' + c.date,
      time: c.date || 'Recent',
      badge: c.status === 'pending' ? 'Pending' : 'Answered',
      badgeColor: c.status === 'pending' ? 'orange' : 'green',
      icon: av(c.student),
      action: '<button class="small-btn" style="padding:5px 12px; font-size:12px;" onclick="markTNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'t-consultation\')">Review</button>'
    });
  });

  // 2. Ratings & Feedback
  ratings.filter(function(r){ return r.teacher === tName; }).forEach(function(r){
    var k = 'r_' + r.student + '_' + r.stars + '_' + (r.feedback ? r.feedback.slice(0, 15) : '');
    var isNew = !readTNotifs[k];
    var isAnon = r.isAnonymous || r.student === 'Anonymous Student';
    var dispName = isAnon ? 'Anonymous Student' : r.student;
    var icon = isAnon ? '<div class="av" style="background:#94a3b8;">?</div>' : av(r.student);
    items.push({
      type: 'feedback',
      key: k,
      isNew: isNew,
      title: dispName + ' rated you ' + '★'.repeat(r.stars) + ' (' + r.stars + ' Stars)',
      detail: r.feedback ? '“' + r.feedback + '”' : 'Rated ' + r.stars + ' Stars without written comment.',
      time: isAnon ? 'Anonymous Feedback' : 'Student Feedback',
      badge: r.stars + '★ Feedback',
      badgeColor: r.stars >= 4 ? 'green' : 'orange',
      icon: icon,
      action: '<button class="small-btn ghost" style="padding:5px 12px; font-size:12px;" onclick="markTNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'t-rating\')">View Feedback</button>'
    });
  });

  // 3. Direct Messages from students
  Object.keys(sharedMsgs).forEach(function(key){
    var parts = key.split('||');
    if(parts[0] === tName){
      var studentName = parts[1];
      var msgs = sharedMsgs[key] || [];
      var lastStudentMsg = null;
      var lastStudentMsgIdx = -1;
      for(var i = msgs.length - 1; i >= 0; i--){
        if(msgs[i].from === 'student'){
          lastStudentMsg = msgs[i];
          lastStudentMsgIdx = i;
          break;
        }
      }
      if(lastStudentMsg){
        var k = 'tmsg_' + studentName + '_' + lastStudentMsgIdx + '_' + (lastStudentMsg.text || '').slice(0, 15);
        var isNew = !readTNotifs[k];
        items.push({
          type: 'message',
          key: k,
          isNew: isNew,
          title: 'Direct message from ' + studentName,
          detail: '“' + lastStudentMsg.text + '”',
          time: 'Direct Message',
          badge: 'Message',
          badgeColor: 'cyan',
          icon: av(studentName),
          action: '<button class="small-btn" style="padding:5px 12px; font-size:12px;" onclick="markTNotifRead(\'' + k.replace(/'/g, "\\'") + '\', \'t-messages\', \'' + studentName.replace(/'/g, "\\'") + '\')">Reply</button>'
        });
      }
    }
  });

  // 4. Announcements
  announcements.filter(function(a){ return !isConsultReminder(a); }).forEach(function(a){
    var k = 'ta_' + a.id;
    var isNew = !readTNotifs[k];
    items.push({
      type: 'announcements',
      key: k,
      isNew: isNew,
      title: a.title ? a.title : ('Notice from ' + a.author),
      detail: a.text,
      time: a.created_at || 'Recent',
      badge: a.category || 'Notice',
      badgeColor: 'orange',
      icon: '<div class="day" style="font-size:18px;">📢</div>',
      action: '<button class="small-btn ghost" style="padding:5px 12px; font-size:12px;" onclick="markTNotifRead(\'' + k + '\', \'t-announcements\')">View Notice</button>'
    });
  });

  var unreadCount = items.filter(function(x){ return x.isNew; }).length;
  var badgeEl = document.getElementById('t-notif-badge');
  if(badgeEl){
    badgeEl.textContent = unreadCount;
    badgeEl.style.display = unreadCount > 0 ? 'inline-block' : 'none';
  }

  if(tNotifFilter && tNotifFilter !== 'all'){
    items = items.filter(function(x){ return x.type === tNotifFilter; });
  }

  if(!items.length){
    el.innerHTML = '<div class="empty">No faculty notifications yet.</div>';
    return;
  }

  el.innerHTML = items.map(function(item){
    return '<div class="list-item rich notif-card' + (item.isNew ? ' is-new' : '') + '" onclick="if(event.target.tagName !== \'BUTTON\'){ markTNotifRead(\'' + item.key.replace(/'/g, "\\'") + '\'); }" style="align-items:center; padding:14px; border-radius:12px; margin-bottom:10px; cursor:pointer;">'
      + item.icon
      + '<div class="gr" style="flex:1;">'
      +   '<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">'
      +     '<span class="notif-title" style="font-weight:700; font-size:13.5px; color:var(--navy-deep);">' + item.title + '</span>'
      +     '<div style="display:flex; gap:6px; align-items:center;">'
      +       '<span class="pill ' + item.badgeColor + '" style="font-size:11px;">' + item.badge + '</span>'
      +       (item.isNew ? '<span class="pill green" style="font-size:10px;">NEW</span>' : '')
      +       '<small style="color:var(--muted); font-size:11px;">' + item.time + '</small>'
      +     '</div>'
      +   '</div>'
      +   '<small style="color:var(--muted); margin-top:2px; display:block;">' + item.detail + '</small>'
      + '</div>'
      + (item.action ? '<div style="margin-left:12px;">' + item.action + '</div>' : '')
      + '</div>';
  }).join('');
}
window.filterTNotifications = filterTNotifications;
window.clearAllTNotifications = clearAllTNotifications;
window.markTNotifRead = markTNotifRead;
window.renderTNotifications = renderTNotifications;

/* ============================================================
   INIT ON LOAD & SESSION RESTORATION
   ============================================================ */
function restorePortalSession(){
  try {
    var savedRole = localStorage.getItem('portal_session_role');
    var savedAccStr = localStorage.getItem('portal_session_account');
    var savedSec = localStorage.getItem('portal_current_sec');
    if(savedRole && savedAccStr){
      var savedAcc = JSON.parse(savedAccStr);
      if(savedAcc && (savedAcc.id || savedAcc.name)){
        var roleList = (ACCOUNTS && ACCOUNTS[savedRole]) ? ACCOUNTS[savedRole] : [];
        var liveAcc = roleList.find(function(a){ return a.id === savedAcc.id || a.name === savedAcc.name; }) || savedAcc;
        enterApp(savedRole, liveAcc);
        if(savedSec){
          go(savedRole, savedSec);
        }
        return true;
      }
    }
  } catch(e){}
  return false;
}

window.addEventListener('load',function(){
  renderSChat();
  renderTChat();
  restorePortalSession();
});
restorePortalSession();
