<script>
(function(){
var IC=[['history','🕘'],['home','🏠'],['dashboard','🏠'],['schedule','🗓️'],['teacher','👩‍🏫'],['consult','📋'],['message','✉️'],['announce','📢'],['notif','🔔'],['profile','👤'],['rating','⭐'],['student','🎓'],['user','👥'],['report','📊'],['setting','⚙️']];
function icons(){document.querySelectorAll('.sidebar-link').forEach(function(a){if(a.dataset.ic)return;a.dataset.ic=1;var t=a.textContent.toLowerCase(),e='•';for(var i=0;i<IC.length;i++)if(t.indexOf(IC[i][0])>-1){e=IC[i][1];break}var s=document.createElement('span');s.className='ic';s.textContent=e;a.insertBefore(s,a.firstChild)})}
function hero(role,acc){var app=document.getElementById(role+'App');if(!app)return;var main=app.querySelector('.main');if(!main)return;var o=main.querySelector('.hero');if(o)o.remove();var h=new Date().getHours(),g=h<12?'Good morning':h<18?'Good afternoon':'Good evening';var nm=role==='student'?acc.name.split(' ')[0]:acc.name;var sub={student:'Here is what is happening with your consultations.',teacher:'Review pending consultations and reply to students.',admin:'Overview of everything running on the portal.'}[role];var d=document.createElement('div');d.className='hero';d.innerHTML='<div><h2>'+g+', '+nm+' 👋</h2><p>'+new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})+' · '+sub+'</p></div><div class="qa"></div>';var qa=d.querySelector('.qa');[].slice.call(app.querySelectorAll('.sidebar-link')).slice(1,4).forEach(function(l){var b=document.createElement('button');b.textContent=l.textContent;b.onclick=function(){l.click()};qa.appendChild(b)});var tb=main.querySelector('.topbar');main.insertBefore(d,tb?tb.nextSibling:main.firstChild)}
var _e=window.enterApp;window.enterApp=function(r,a){_e(r,a);icons();hero(r,a)};

var lb=document.querySelector('.left-bottom');if(lb){var u=document.createElement('ul');u.className='feat';u.innerHTML='<li>Book consultations with your teachers</li><li>Message teachers privately</li><li>Rate teachers and read announcements</li>';lb.insertBefore(u,lb.querySelector('.left-foot'))}
['loginId','loginPw'].forEach(function(i){var e=document.getElementById(i);if(e)e.addEventListener('keydown',function(k){if(k.key==='Enter')doLogin()})});
var t=document.createElement('button');t.id='themeBtn';t.title='Toggle dark mode';t.setAttribute('aria-label','Toggle dark mode');
var savedTheme=null;try{savedTheme=localStorage.getItem('portal_theme')}catch(e){}
if(savedTheme==='dark'||document.documentElement.classList.contains('dark')){document.body.classList.add('dark');t.textContent='☀️'}else{t.textContent='🌙'}
t.onclick=function(){var d=document.body.classList.toggle('dark');t.textContent=d?'☀️':'🌙';try{localStorage.setItem('portal_theme',d?'dark':'light')}catch(e){}};document.body.appendChild(t);
icons();
})();
</script>
<script>
(function(){
var T=teacherData.map(function(t){return t.name});
ACCOUNTS.teacher.forEach(function(a){if(T.indexOf(a.name)===-1)T.push(a.name);});
var S=ACCOUNTS.student.map(function(a){return a.name});
consultations.forEach(function(c){if(c.student && S.indexOf(c.student)===-1)S.push(c.student);});
Object.keys(sharedMsgs).forEach(function(k){
  var p=k.split('||');
  if(p[0] && T.indexOf(p[0])===-1) T.push(p[0]);
  if(p[1] && S.indexOf(p[1])===-1) S.push(p[1]);
});
function inn(n,a){return a.indexOf(n)>-1}
function ok(c){return inn(c.teacher,T)&&inn(c.student,S)}
window.teacherData=teacherData;
window.consultations=consultations.filter(ok);window.schedules=schedules.filter(ok);window.ratings=ratings.filter(ok);
window.announcements=announcements.filter(function(a){
  if(isConsultReminder(a)) return false;
  return inn(a.author,T)||a.author==='Admin'||a.author==='System Administrator'||a.author==='admin'||!a.author;
});
if(typeof updateTeacherDropdowns==='function') updateTeacherDropdowns();
var me = window.me || function(){ return (currentAccount && currentAccount.name) ? currentAccount.name : 'Reimark Amaro'; };
var ini = window.ini || window.initials;
var av = window.av || function(n){ return '<div class="av">' + ini(n) + '</div>'; };
var pl = window.pl || function(t,c){ return '<span class="pill '+c+'">'+t+'</span>'; };
function rich(n,t,s,p){return '<div class="list-item rich">'+av(n)+'<div class="gr"><b>'+t+'</b><small>'+s+'</small></div>'+p+'</div>'}
function ann(a){
  var cat = a.category || 'General';
  var catPill = {Academic:'cyan', Consultation:'orange', Urgent:'red', Reminder:'green'}[cat] || 'orange';
  var time = a.created_at || 'Recently';
  return '<div class="list-item rich ann-card" style="align-items:flex-start; padding:14px; border-radius:12px; background:#fff; border:1px solid var(--line); margin-bottom:10px;">'
    + '<div class="day" style="font-size:18px;">📢</div>'
    + '<div class="gr" style="flex:1;">'
    +   '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px; gap:8px; flex-wrap:wrap;">'
    +     '<span style="font-weight:700; font-size:14.5px; color:var(--navy-deep);">' + (a.title || 'Announcement') + '</span>'
    +     '<div style="display:flex; gap:6px; align-items:center;">'
    +       '<span class="pill ' + catPill + '" style="font-size:11px;">' + cat + '</span>'
    +       '<small style="color:var(--muted); font-size:11px;">' + time + '</small>'
    +     '</div>'
    +   '</div>'
    +   '<p style="margin:4px 0 8px; font-size:13.5px; line-height:1.45; color:var(--ink);">' + a.text + '</p>'
    +   '<small style="color:var(--muted);">Posted by <b style="color:var(--navy);">' + a.author + '</b></small>'
    + '</div>'
    + '</div>';
}
function st(c){return pl(c.status,c.status==='pending'?'orange':'green')}
function tcards(){
  return '<div class="tgrid">'+teacherData.map(function(t){
    var o=t.status==='available';
    var em=t.email||(t.name.toLowerCase().replace(/[^a-z]/g,'')+'.faculty@icp.edu.ph');
    return '<div class="tc">'
      + '<div class="top">'+av(t.name)+'<div><h4>'+t.name+'</h4><p>'+t.subject+'</p></div></div>'
      + '<div class="meta" style="color:var(--cyan-deep); font-size:12.5px; word-break:break-all;">✉️ <a href="mailto:'+em+'" style="color:inherit; text-decoration:none; font-weight:600;">'+em+'</a></div>'
      + '<div class="meta">🗓️ '+t.days+' · 🕐 '+t.time+'</div>'
      + '<p style="font-size:13px; color:var(--muted); margin:4px 0 8px;">'+(t.bio||'')+'</p>'
      + '<div>'+pl(o?'Available':'Unavailable',o?'green':'orange')+'</div>'
      + '<div class="btns">'
      +   '<button class="small-btn" onclick="jump(\'s-consultation\')">Book Consultation</button>'
      +   '<button class="small-btn ghost" onclick="openSChat(\'' + t.name.replace(/'/g, "\\'") + '\'); jump(\'s-messages\');">Message</button>'
      + '</div></div>';
  }).join('')+'</div>';
}
window.tcards=tcards;window.jump=function(s){var l=document.querySelector('#studentApp [data-sec="'+s+'"]');if(l)l.click()};
window.showTeacherView=function(v){document.querySelectorAll('#sec-s-home .panel:nth-of-type(1) .sub-tab').forEach(function(b){b.classList.toggle('active',b.getAttribute('onclick')==="showTeacherView('"+v+"')")});document.getElementById('teacherViewBody').innerHTML=tcards()};
window.showConsultView=function(v){document.querySelectorAll('#sec-s-home .panel:nth-of-type(2) .sub-tab').forEach(function(b){b.classList.toggle('active',b.getAttribute('onclick')==="showConsultView('"+v+"')")});document.getElementById('consultViewBody').innerHTML=consultations.filter(function(c){return c.student===me()&&c.status===v}).map(function(c){return rich(c.teacher,c.teacher+' — '+c.topic,c.reply?'Reply: '+c.reply:'Waiting for a reply · '+c.date,st(c))}).join('')||'<div class="empty">Nothing here yet.</div>'};
window.renderSHistory=function(){var t=document.getElementById('s-history-table');if(!t)return;var h='<tr><th>Date</th><th>Teacher</th><th>Topic</th><th>Reply</th><th>Status</th></tr>';consultations.filter(function(c){return c.student===me()}).forEach(function(c){h+='<tr><td>'+c.date+'</td><td><b>'+c.teacher+'</b></td><td>'+c.topic+'</td><td style="color:var(--muted)">'+(c.reply||'Awaiting reply…')+'</td><td>'+st(c)+'</td></tr>'});t.innerHTML=h};

window.renderSAnnouncements=function(filterCat){
  var e=document.getElementById('s-announce-list');if(!e)return;
  var list=announcements.filter(function(a){ return !isConsultReminder(a); });
  if(filterCat && filterCat!=='all'){
    list=list.filter(function(a){return (a.category||'General').toLowerCase()===filterCat.toLowerCase();});
  }
  e.innerHTML=list.map(ann).join('')||'<div class="empty">No announcements matching this category.</div>';
};
window.filterSAnnouncements=function(cat){
  document.querySelectorAll('#s-ann-filter-tabs .sub-tab').forEach(function(b){
    b.classList.toggle('active',b.getAttribute('onclick')==="filterSAnnouncements('"+cat+"')");
  });
  window.renderSAnnouncements(cat);
};

window.renderTAnnouncements = renderTAnnouncements;
window.filterTAnnTab = filterTAnnTab;
window.filterSNotifications = filterSNotifications;
window.clearAllNotifications = clearAllNotifications;
window.markNotifRead = markNotifRead;
window.renderSNotifications = renderSNotifications;
window.filterTNotifications = filterTNotifications;
window.clearAllTNotifications = clearAllTNotifications;
window.markTNotifRead = markTNotifRead;
window.renderTNotifications = renderTNotifications;
window.renderTeacherDashboardList=function(){var el=document.getElementById('t-student-list');if(!el)return;var h='<tr><th>Student</th><th>Topic</th><th>Status</th></tr>';getStudentsForTeacher(me()).forEach(function(c){h+='<tr><td><b>'+c.student+'</b></td><td>'+c.topic+'</td><td>'+st(c)+'</td></tr>'});el.innerHTML=h};
window.renderTeacherSchedule=function(){
  var myName = me();
  var tObj = teacherData.find(function(x){ return x.name === myName; });
  var subInp = document.getElementById('t-subject-topic');
  if(subInp && tObj && tObj.subject){
    subInp.value = tObj.subject;
  }
  var cb = document.getElementById('t-status-toggle');
  var lbl = document.getElementById('t-status-label');
  if(cb && lbl && tObj){
    cb.checked = (tObj.status === 'available');
    lbl.textContent = (tObj.status === 'available' ? 'Available' : 'Unavailable');
    lbl.className = 'pill ' + (tObj.status === 'available' ? 'green' : 'orange');
  }
  var myS = schedules.filter(function(s){ return s.teacher === myName; });
  var listHtml = myS.map(function(s){
    return '<div class="list-item rich"><div class="day">'+s.day+'</div><div class="gr"><b>'+s.student+'</b><small>'+s.topic+' · '+s.time+'</small></div><span class="pill green" style="font-size:11px;">Confirmed</span></div>';
  }).join('') || '<div class="empty">No upcoming schedules.</div>';

  var el1 = document.getElementById('t-schedule-list');
  if(el1) el1.innerHTML = listHtml;
  var el2 = document.getElementById('t-schedule-list2');
  if(el2) el2.innerHTML = listHtml;
};
window.renderTeacherRating=function(){
  var el=document.getElementById('t-rating-list');if(!el)return;
  var m=ratings.filter(function(r){return r.teacher===me()});
  if(!m.length){el.innerHTML='<div class="empty">No ratings yet.</div>';return}
  var a=(m.reduce(function(s,r){return s+r.stars},0)/m.length).toFixed(1);
  var h='<div class="sum"><div><div class="big">'+a+'</div><div class="stars" style="color:#F2A33A">'+'★'.repeat(Math.round(a))+'</div><small>'+m.length+' review'+(m.length>1?'s':'')+'</small></div><div class="bars">';
  for(var i=5;i>0;i--){var n=m.filter(function(r){return r.stars===i}).length;h+='<div class="bar">'+i+'★<i><b style="width:'+n/m.length*100+'%"></b></i>'+n+'</div>'}
  h+='</div></div><div style="display:flex; flex-direction:column; gap:10px; margin-top:14px;">'+m.map(function(r){
    var stars='★'.repeat(r.stars)+'☆'.repeat(5-r.stars);
    var isAnon = r.isAnonymous || r.student === 'Anonymous Student';
    var dispName = isAnon ? 'Anonymous Student' : r.student;
    var badge=pl(r.stars+' Star'+(r.stars>1?'s':''),r.stars>=4?'green':'orange');
    var anonBadge = isAnon ? '<span class="pill orange" style="font-size:10px; margin-left:4px;">Anonymous</span>' : '';
    var fb=r.feedback?'<div class="feedback-quote" style="margin-top:8px; padding:10px 14px; background:rgba(44,178,224,0.08); border-left:3px solid var(--cyan-deep); border-radius:6px; font-size:13.5px; color:var(--ink); font-style:italic; line-height:1.45;">“'+r.feedback+'”</div>':'<div style="margin-top:6px; font-size:12.5px; color:var(--muted); font-style:italic;">No written feedback comment provided.</div>';
    var icon = isAnon ? '<div class="av" style="background:#94a3b8;">?</div>' : av(r.student);
    return '<div class="list-item rich rating-card" style="align-items:flex-start; padding:14px 16px; border-radius:12px; border:1px solid var(--line); margin-bottom:8px;">'+icon+'<div class="gr" style="flex:1;"><div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;"><b style="font-size:14.5px;">'+dispName+'</b><div style="display:flex; gap:8px; align-items:center;"><span style="color:#F2A33A; font-size:15px; letter-spacing:1px;">'+stars+'</span>'+badge+anonBadge+'</div></div>'+fb+'</div></div>';
  }).join('')+'</div>';
  el.innerHTML=h;
};
window.tHomeView=function(v){
  document.querySelectorAll('#sec-t-home .sub-tab').forEach(function(b){
    b.classList.toggle('active',b.getAttribute('onclick')==="tHomeView('"+v+"')");
  });
  var b=document.getElementById('tHomeBody');
  b.innerHTML=v==='announce'?announcements.filter(function(a){ return !isConsultReminder(a); }).map(ann).join('')||'<div class="empty">No announcements.</div>':ratings.filter(function(r){return r.teacher===me()}).map(function(r){
    var stars='★'.repeat(r.stars)+'☆'.repeat(5-r.stars);
    var isAnon = r.isAnonymous || r.student === 'Anonymous Student';
    var dispName = isAnon ? 'Anonymous Student' : r.student;
    var icon = isAnon ? '<div class="av" style="background:#94a3b8;">?</div>' : av(r.student);
    return '<div class="list-item rich rating-card" style="align-items:flex-start; padding:12px 14px; border-radius:10px; border:1px solid var(--line); margin-bottom:8px;">'+icon+'<div class="gr" style="flex:1;"><div style="display:flex; justify-content:space-between; align-items:center; gap:6px;"><b>'+dispName+'</b><span style="color:#F2A33A; font-size:14px;">'+stars+'</span></div>'+(r.feedback?'<p style="margin:4px 0 0; font-size:13px; color:var(--ink); font-style:italic;">“'+r.feedback+'”</p>':'')+'</div></div>';
  }).join('')||'<div class="empty">No feedback yet.</div>';
};
function dots(role,secs){secs.forEach(function(s){var l=document.querySelector('#'+role+'App [data-sec="'+s+'"]');if(!l||l.querySelector('.rdot'))return;var d=document.createElement('span');d.className='rdot';l.appendChild(d);l.addEventListener('click',function(){var x=l.querySelector('.rdot');if(x)x.remove()})})}
var _e=window.enterApp;window.enterApp=function(r,a){
  _e(r,a);
  if(r==='student'){
    var p=document.querySelector('#sec-s-teachers .panel');
    if(p)p.innerHTML='<h3>Teachers &amp; Schedule</h3>'+tcards();
    dots('student',['s-notifications','s-messages']);
    renderStudentProfile();
  }
  if(r==='teacher'){
    var n=consultations.filter(function(c){return c.teacher===a.name&&c.status==='pending'}).length;
    dots('teacher',n?['t-consultation','t-messages']:['t-messages']);
    renderTeacherProfile();
    renderTeacherSchedule();
    renderTAnnouncements();
  }
  if(r==='admin'){
    updateAdminCards();
    renderAdminUsers();
    renderAdminProfile();
  }
};
})();
</script>
<style id="mobile-polish">
html{scroll-behavior:smooth}
a,button{-webkit-tap-highlight-color:transparent;touch-action:manipulation}
.panel,.card,.tc,.list-item{transition:box-shadow .2s ease,transform .2s ease}
@media (hover:hover){.card:hover,.tc:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(11,30,66,.12)}}
:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}

@media (max-width:820px){
