    flex-direction:row!important;overflow-x:auto;gap:2px!important;padding:6px 6px calc(6px + env(safe-area-inset-bottom))!important;
    background:rgba(11,30,66,.97)!important;backdrop-filter:blur(10px);box-shadow:0 -6px 24px rgba(0,0,0,.25)!important;scroll-snap-type:x proximity}
  .app.active .sidebar-link{flex:0 0 auto;flex-direction:column;justify-content:center;gap:3px!important;min-width:68px;max-width:84px;padding:7px 6px!important;
    font-size:10px!important;line-height:1.2;text-align:center;border-radius:12px!important;scroll-snap-align:center;transform:none!important}
  .app.active .sidebar-link .ic{font-size:19px}
  .app.active .sidebar-link.active{box-shadow:none!important;background:var(--cyan-deep)!important}
  .app.active .main{padding:max(58px,calc(env(safe-area-inset-top) + 50px)) 14px 24px!important}
  .topbar{position:relative}
  .hero{padding:20px!important;border-radius:16px!important}
