  .hero .qa{width:100%}.hero .qa button{flex:1 1 auto}
  .toast,.cc-toast{bottom:calc(88px + env(safe-area-inset-bottom))!important}
}
@media (max-width:600px){
  .panel{border-radius:14px!important;padding:16px 14px!important}
  .flex-form{flex-direction:column}
  .flex-form .small-btn{width:100%}
  .form-wrap{padding:26px 20px!important;border-radius:16px!important}
  /* tables become stacked cards */
  .panel table,.panel tbody,.panel tr,.panel td{display:block!important;width:100%;white-space:normal!important}
  .panel thead{display:none!important}
  .panel tr{background:#F4F9FE;border:1px solid var(--line);border-radius:12px;padding:8px 12px;margin-bottom:10px}
  .panel td{border:0!important;padding:5px 0!important;text-align:left!important}
  .panel td[data-label]:before{content:attr(data-label);display:block;font:700 10px Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:1px}
  .dark .panel tr{background:#1B2F57;border-color:#2A4170}
  .messenger-chat-body{max-height:50vh}
}
@media (max-width:820px) and (orientation:landscape){
  .app.active .sidebar-link span:not(.ic){display:none}
  .app.active{padding-bottom:calc(54px + env(safe-area-inset-bottom))}
}
</style>
<script>
(function(){
  function label(t){
    var th=[].map.call(t.querySelectorAll('thead th'),function(x){return x.textContent.trim()});
    if(!th.length)return;
    t.querySelectorAll('tbody tr').forEach(function(r){
      [].forEach.call(r.children,function(td,i){if(!td.hasAttribute('colspan')&&th[i]&&!td.dataset.label)td.dataset.label=th[i]});
    });
  }
  function run(){document.querySelectorAll('table').forEach(label)}
  var busy=false;
  new MutationObserver(function(){if(busy)return;busy=true;setTimeout(function(){run();busy=false},50)})
    .observe(document.body,{childList:true,subtree:true});
  run();
  var g=window.go;
  if(typeof g==='function')window.go=function(){
    var r=g.apply(this,arguments);
    setTimeout(function(){
      var a=document.querySelector('.app.active .sidebar-link.active');
      if(a&&a.scrollIntoView)a.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'});
      window.scrollTo({top:0});
    },30);
    return r;
  };
})();
</script>
