<style id="dark-mode-complete">
/* ============================================================
   GLOBAL & AUTH DARK THEME
   ============================================================ */
body.dark {
  --cream: #071022;
  --paper: #101D38;
  --paper-deep: #0A1530;
  --ink: #E6ECF7;
  --muted: #9AA9C4;
  --line: #2A3D66;
  background: #071022 !important;
  color: #E6ECF7 !important;
}

body.dark #authStage { background: #071022 !important; }
body.dark #authStage .panel-left::before { background: rgba(5,10,35,.55); }
body.dark #authStage .panel-right { background: #071022 !important; }
body.dark #authStage .form-wrap {
  background: #101d38 !important;
  border: 1px solid #2A3D66 !important;
  color: var(--ink);
  box-shadow: 0 18px 44px rgba(0,0,0,.55) !important;
}
body.dark #authStage .form-wrap h2,
body.dark #authStage .form-top-text .title2 { color: #fff !important; }
body.dark #authStage .eyebrow2 { color: var(--cyan); }
