body.dark #authStage .hint { color: #9AA9C4; }
body.dark #authStage .field label,
body.dark #authStage .pw-toggle { color: #C9D6EE; }
body.dark #authStage .field input {
  background: #0A1530 !important;
  border-color: #2A3D66 !important;
  color: #E6ECF7 !important;
  caret-color: var(--cyan);
}
body.dark #authStage .field input::placeholder { color: #5F7092; }
body.dark #authStage .field input:focus {
  border-color: var(--cyan) !important;
  box-shadow: 0 0 0 3px rgba(44,178,224,.22) !important;
}
body.dark #authStage .field input:-webkit-autofill {
  -webkit-box-shadow: 0 0 0 40px #0A1530 inset !important;
  -webkit-text-fill-color: #E6ECF7 !important;
}
body.dark #authStage .btn-primary {
  background: linear-gradient(135deg, var(--cyan-deep), var(--cyan)) !important;
  color: #06142e;
  box-shadow: 0 8px 20px rgba(44,178,224,.3) !important;
