  background: #101D38 !important;
  color: #FDE047 !important;
  border-color: #2A3D66 !important;
  box-shadow: 0 4px 14px rgba(0,0,0,.4) !important;
}

/* Panels and Cards */
body.dark .panel,
body.dark .card,
body.dark .form-wrap {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
  color: #E6ECF7 !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.35) !important;
}

/* Headings and primary titles */
body.dark h1,
body.dark h2,
body.dark h3,
body.dark h4,
body.dark .topbar h1,
body.dark .panel h3,
body.dark .card-value,
