  border-color: #2A3D66 !important;
  color: #E6ECF7 !important;
}
body.dark .logout-btn:hover {
  background: #16264A !important;
  border-color: var(--cyan) !important;
  color: #FFFFFF !important;
}

/* Form controls, textareas, selects & option elements */
body.dark input,
body.dark textarea,
body.dark select,
body.dark .field input,
body.dark .field select,
body.dark .panel input,
body.dark .panel select {
  background: #0A1530 !important;
  border-color: #2A3D66 !important;
  color: #E6ECF7 !important;
}
body.dark select option {
  background: #0A1530 !important;
  color: #E6ECF7 !important;
}
body.dark input::placeholder,
body.dark textarea::placeholder {
  color: #5F7092 !important;
}
body.dark input:focus,
body.dark textarea:focus,
body.dark select:focus {
  border-color: var(--cyan) !important;
  box-shadow: 0 0 0 3px rgba(44,178,224,.25) !important;
}
body.dark .field label { color: #C9D6EE !important; }

/* Tables */
body.dark table { border-collapse: collapse; }
body.dark th {
  background: #0A1530 !important;
  color: #9AA9C4 !important;
  border-bottom: 2px solid #2A3D66 !important;
}
body.dark td {
  color: #E6ECF7 !important;
  border-bottom: 1px solid #1E2D4A !important;
  background: transparent !important;
}
body.dark tr:nth-child(even) td {
  background: rgba(16, 29, 56, 0.45) !important;
}
body.dark tr:hover td {
  background: #1B2F57 !important;
}

/* Announcements & Notifications Cards */
body.dark .list-item {
  border-bottom-color: #1E2D4A !important;
  color: #E6ECF7 !important;
}
body.dark .list-item:hover { background: #16264A !important; }
body.dark .list-item.rich {
  background: #101D38 !important;
  border: 1px solid #2A3D66 !important;
  color: #E6ECF7 !important;
}
body.dark .list-item.rich:hover {
  background: #142446 !important;
  border-color: #3B5282 !important;
}
body.dark .list-item.rich p { color: #CBD5E1 !important; }
body.dark .list-item.rich small { color: #9AA9C4 !important; }
body.dark .day {
  background: #16264A !important;
  color: var(--cyan) !important;
}
body.dark .ann-card {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
}
body.dark .notif-card {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
}
body.dark .notif-card.is-new,
body.dark .list-item.rich[style*="#F0F7FF"] {
  background: #14284F !important;
  border-color: rgba(44, 178, 224, 0.6) !important;
  box-shadow: 0 0 12px rgba(44, 178, 224, 0.15) !important;
}

/* Messenger in dark mode */
body.dark .messenger-wrap {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
  box-shadow: 0 10px 30px rgba(0,0,0,.4) !important;
}
body.dark .messenger-list {
  background: #101D38 !important;
  border-right-color: #2A3D66 !important;
}
body.dark .messenger-list-header {
  background: #0A1530 !important;
  color: var(--cyan) !important;
  border-bottom-color: #2A3D66 !important;
}
body.dark #s-msg-search,
body.dark #t-msg-search {
  background: #0A1530 !important;
  color: #E6ECF7 !important;
  border: 1px solid #2A3D66 !important;
}
body.dark #s-msg-search:focus,
body.dark #t-msg-search:focus {
  border-color: var(--cyan) !important;
}
body.dark .messenger-contact {
  background: transparent !important;
  border-bottom-color: #1E2D4A !important;
}
body.dark .messenger-contact:hover {
  background: #16264A !important;
}
body.dark .messenger-contact.active {
  background: #192D54 !important;
  border-left: 3px solid var(--cyan) !important;
}
body.dark .messenger-contact-name { color: #F8FAFC !important; }
body.dark .messenger-contact-preview { color: #9AA9C4 !important; }
body.dark .messenger-chat { background: #101D38 !important; }
body.dark .messenger-chat-header {
  background: #0A1530 !important;
  color: #F8FAFC !important;
  border-bottom-color: #2A3D66 !important;
}
body.dark .messenger-chat-header span { color: #F8FAFC !important; }
body.dark .messenger-chat-body { background: #081124 !important; }
body.dark .msg-bubble.received {
  background: #16264A !important;
  color: #E6ECF7 !important;
  border-color: #2A3D66 !important;
  box-shadow: 0 2px 8px rgba(0,0,0,.35) !important;
}
body.dark .msg-bubble.sent {
  background: linear-gradient(135deg, #1B5E91, #1565C0) !important;
  color: #FFFFFF !important;
  box-shadow: 0 2px 8px rgba(21, 101, 192, 0.3) !important;
}
body.dark .messenger-chat-footer {
  background: #0A1530 !important;
  border-top-color: #2A3D66 !important;
}
body.dark .messenger-chat-footer input {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
  color: #E6ECF7 !important;
}
body.dark .messenger-chat-footer input:focus { border-color: var(--cyan) !important; }
body.dark .messenger-send-btn {
  background: linear-gradient(135deg, var(--cyan-deep), var(--cyan)) !important;
  color: #06142E !important;
  font-weight: 700 !important;
}
body.dark .messenger-avatar {
  background: linear-gradient(135deg, #16264A, #1B5E91) !important;
  color: #FFFFFF !important;
}

/* Teacher cards */
body.dark .tc {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
}
body.dark .tc:hover {
  border-color: var(--cyan-deep) !important;
  box-shadow: 0 12px 28px rgba(0,0,0,.45) !important;
}
body.dark .tc h4 { color: #F8FAFC !important; }
body.dark .tc .meta { color: #9AA9C4 !important; }
body.dark .tc .meta a { color: var(--cyan) !important; }

/* Ratings & Feedback */
body.dark .sum .big { color: #F8FAFC !important; }
body.dark .sum small { color: #9AA9C4 !important; }
body.dark .bar { color: #CBD5E1 !important; }
body.dark .bar i { background: #16264A !important; }
body.dark .bar i b {
  background: linear-gradient(90deg, #F2A33A, #F7C873) !important;
}
body.dark .rating-card {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
}
body.dark .feedback-quote {
  background: rgba(44, 178, 224, 0.12) !important;
  border-left-color: var(--cyan) !important;
  color: #E2E8F0 !important;
}
body.dark #rf-msg {
  background: rgba(34, 122, 60, 0.25) !important;
  color: #4ADE80 !important;
  border: 1px solid rgba(74, 222, 128, 0.4) !important;
}

/* Pills in dark mode */
body.dark .pill.green {
  background: rgba(34, 122, 60, 0.3) !important;
  color: #4ADE80 !important;
  border: 1px solid rgba(74, 222, 128, 0.35) !important;
}
body.dark .pill.orange {
  background: rgba(180, 97, 15, 0.3) !important;
  color: #FB923C !important;
  border: 1px solid rgba(251, 146, 60, 0.35) !important;
}
body.dark .pill.pink,
body.dark .pill.red {
  background: rgba(180, 35, 47, 0.3) !important;
  color: #F87171 !important;
  border: 1px solid rgba(248, 113, 113, 0.35) !important;
}
body.dark .pill.cyan {
  background: rgba(44, 178, 224, 0.25) !important;
  color: #38BDF8 !important;
  border: 1px solid rgba(56, 189, 248, 0.35) !important;
}
body.dark .pill[style*="var(--paper)"] {
  background: #16264A !important;
  color: #CBD5E1 !important;
}

/* Modals & Toasts */
body.dark .cc-box {
  background: #101D38 !important;
  color: #E6ECF7 !important;
  border: 1px solid #2A3D66 !important;
  box-shadow: 0 20px 50px rgba(0,0,0,.75) !important;
}
body.dark .cc-box p { color: #F8FAFC !important; }
body.dark .cc-box textarea {
  background: #0A1530 !important;
  color: #E6ECF7 !important;
  border-color: #2A3D66 !important;
}
body.dark .cc-toast {
  background: #16264A !important;
  color: #FFFFFF !important;
  border: 1px solid #2A3D66 !important;
  box-shadow: 0 10px 30px rgba(0,0,0,.5) !important;
}

/* Profile in dark mode */
body.dark .profile-head {
  background: linear-gradient(120deg, #101D38, #16264A) !important;
  border: 1px solid #2A3D66 !important;
}
body.dark .profile-avatar-lg { border-color: #2A3D66 !important; }
body.dark code {
  background: rgba(44, 178, 224, 0.2) !important;
  color: var(--cyan) !important;
}

/* Notification and announcement cards in dark mode */
.notif-card {
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink);
  transition: all .15s ease;
}
.notif-card.is-new {
  background: #F0F7FF;
  border-color: var(--cyan-deep);
}
body.dark .notif-card {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
  color: #E6ECF7 !important;
}
body.dark .notif-card.is-new {
  background: #16264A !important;
  border-color: var(--cyan) !important;
}
body.dark .notif-title {
  color: #F8FAFC !important;
}
body.dark .ann-card {
  background: #101D38 !important;
  border-color: #2A3D66 !important;
}

/* ============================================================
   TAB CLICK ANIMATION & MOBILE (CP) POLISH
   ============================================================ */
@keyframes tabBounce {
  0% { transform: scale(0.92); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}
@keyframes tabGlow {
  0% { box-shadow: 0 0 0 0 rgba(44,178,224,0.6); }
  70% { box-shadow: 0 0 0 8px rgba(44,178,224,0); }
  100% { box-shadow: 0 0 0 0 rgba(44,178,224,0); }
}
.messenger-contact.active {
  background: #E8F2FD !important;
  border-left: 4px solid var(--cyan-deep) !important;
}
body.dark .messenger-contact.active {
  background: #192D54 !important;
  border-left: 4px solid var(--cyan) !important;
}
.sidebar-link {
  transition: all .2s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}
.sidebar-link:active {
  transform: scale(0.93) !important;
}
.sidebar-link.active {
  animation: tabBounce .28s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.sub-tab {
  transition: all .2s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}
.sub-tab:active {
  transform: scale(0.93) !important;
}
.sub-tab.active {
  animation: tabBounce .28s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.messenger-contact {
  transition: all .15s ease !important;
}
.messenger-contact:active {
  transform: scale(0.98) !important;
}

/* CP / Mobile Screen Adjustments (<680px) */
@media (max-width: 680px) {
  /* Messenger phone layout: full width contact list or active chat view */
  .messenger-wrap {
    position: relative !important;
    height: 72vh !important;
    min-height: 480px !important;
    max-height: calc(100dvh - 170px) !important;
    border-radius: 14px !important;
    overflow: hidden !important;
  }
  .messenger-list {
    width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    border-right: none !important;
    border-bottom: none !important;
    display: flex !important;
    flex-direction: column !important;
  }
  .messenger-chat {
    display: none !important;
    width: 100% !important;
    height: 100% !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    z-index: 10 !important;
    background: #fff !important;
  }
  body.dark .messenger-chat {
    background: #14223F !important;
  }
  .messenger-wrap.chat-active .messenger-list {
    display: none !important;
  }
  .messenger-wrap.chat-active .messenger-chat {
    display: flex !important;
  }
  .mobile-back-btn {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
  }

  /* Cleaner mobile headers and cards */
  .topbar {
    padding: 0 4px !important;
    margin-bottom: 14px !important;
  }
  .topbar h1 {
    font-size: 20px !important;
  }
  .cards {
    grid-template-columns: 1fr !important;
    gap: 8px !important;
    margin-bottom: 16px !important;
  }
  .card {
    padding: 12px 14px !important;
    border-radius: 12px !important;
  }
  .card-value {
    font-size: 22px !important;
  }
  .card-label {
    font-size: 11.5px !important;
  }

  /* Compact Hero Banner for Cellphone size */
  .hero {
    padding: 14px 16px !important;
    margin-bottom: 16px !important;
    border-radius: 14px !important;
  }
  .hero h2 {
    font-size: 18px !important;
  }
  .hero p {
    font-size: 12px !important;
  }
  .hero .qa {
    display: none !important;
  }

  /* Form & inputs optimization */
  .field {
    margin-bottom: 12px !important;
  }
  .field label {
    font-size: 11.5px !important;
    margin-bottom: 4px !important;
  }
  input, select, textarea {
    padding: 10px 12px !important;
    border-radius: 8px !important;
  }
  .small-btn {
    width: 100% !important;
    padding: 12px 16px !important;
    font-size: 13.5px !important;
    border-radius: 10px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
  }
  .sub-tabs {
    gap: 6px !important;
    padding-bottom: 6px !important;
  }
  .sub-tab {
    padding: 7px 12px !important;
    font-size: 11.5px !important;
    border-radius: 8px !important;
  }
}
</style>
</body>
</html>